Value *FAddCombine::createNaryFAdd
  (const AddendVect &Opnds, unsigned InstrQuota) {
  assert(!Opnds.empty() && "Expect at least one addend");

  // Step 1: Check if the # of instructions needed exceeds the quota.

  unsigned InstrNeeded = calcInstrNumber(Opnds);
  if (InstrNeeded > InstrQuota)
    return nullptr;

  initCreateInstNum();

  // step 2: Emit the N-ary addition.
  // Note that at most three instructions are involved in Fadd-InstCombine: the
  // addition in question, and at most two neighboring instructions.
  // The resulting optimized addition should have at least one less instruction
  // than the original addition expression tree. This implies that the resulting
  // N-ary addition has at most two instructions, and we don't need to worry
  // about tree-height when constructing the N-ary addition.

  Value *LastVal = nullptr;
  bool LastValNeedNeg = false;

  // Iterate the addends, creating fadd/fsub using adjacent two addends.
  for (const FAddend *Opnd : Opnds) {
    bool NeedNeg;
    Value *V = createAddendVal(*Opnd, NeedNeg);
    if (!LastVal) {
      LastVal = V;
      LastValNeedNeg = NeedNeg;
      continue;
    }

    if (LastValNeedNeg == NeedNeg) {
      LastVal = createFAdd(LastVal, V);
      continue;
    }

    if (LastValNeedNeg)
      LastVal = createFSub(V, LastVal);
    else
      LastVal = createFSub(LastVal, V);

    LastValNeedNeg = false;
  }

  if (LastValNeedNeg) {
    LastVal = createFNeg(LastVal);
  }

#ifndef NDEBUG
  assert(CreateInstrNum == InstrNeeded &&
         "Inconsistent in instruction numbers");
#endif

  return LastVal;
}

Instruction *InstCombinerImpl::
    canonicalizeCondSignextOfHighBitExtractToSignextHighBitExtract(
        BinaryOperator &I) {
  assert((I.getOpcode() == Instruction::Add ||
          I.getOpcode() == Instruction::Or ||
          I.getOpcode() == Instruction::Sub) &&
         "Expecting add/or/sub instruction");

  // We have a subtraction/addition between a (potentially truncated) *logical*
  // right-shift of X and a "select".
  Value *X, *Select;
  Instruction *LowBitsToSkip, *Extract;
  if (!match(&I, m_c_BinOp(m_TruncOrSelf(m_Instruction(
                               Extract, m_LShr(m_Value(X),
                                               m_Instruction(LowBitsToSkip)))),
                           m_Value(Select))))
    return nullptr;

  // `add`/`or` is commutative; but for `sub`, "select" *must* be on RHS.
  if (I.getOpcode() == Instruction::Sub && I.getOperand(1) != Select)
    return nullptr;

  Type *XTy = X->getType();
  bool HadTrunc = I.getType() != XTy;

  // If there was a truncation of extracted value, then we'll need to produce
  // one extra instruction, so we need to ensure one instruction will go away.
  if (HadTrunc && !match(&I, m_c_BinOp(m_OneUse(m_Value()), m_Value())))
    return nullptr;

  // Extraction should extract high NBits bits, with shift amount calculated as:
  //   low bits to skip = shift bitwidth - high bits to extract
  // The shift amount itself may be extended, and we need to look past zero-ext
  // when matching NBits, that will matter for matching later.
  Value *NBits;
  if (!match(LowBitsToSkip,
             m_ZExtOrSelf(m_Sub(m_SpecificInt(XTy->getScalarSizeInBits()),
                                m_ZExtOrSelf(m_Value(NBits))))))
    return nullptr;

  // Sign-extending value can be zero-extended if we `sub`tract it,
  // or sign-extended otherwise.
  auto SkipExtInMagic = [&I](Value *&V) {
    if (I.getOpcode() == Instruction::Sub)
      match(V, m_ZExtOrSelf(m_Value(V)));
    else
      match(V, m_SExtOrSelf(m_Value(V)));
  };

  // Now, finally validate the sign-extending magic.
  // `select` itself may be appropriately extended, look past that.
  SkipExtInMagic(Select);

  CmpPredicate Pred;
  const APInt *Thr;
  Value *SignExtendingValue, *Zero;
  bool ShouldSignext;
  // It must be a select between two values we will later establish to be a
  // sign-extending value and a zero constant. The condition guarding the
  // sign-extension must be based on a sign bit of the same X we had in `lshr`.
  if (!match(Select, m_Select(m_ICmp(Pred, m_Specific(X), m_APInt(Thr)),
                              m_Value(SignExtendingValue), m_Value(Zero))) ||
      !isSignBitCheck(Pred, *Thr, ShouldSignext))
    return nullptr;

  // icmp-select pair is commutative.
  if (!ShouldSignext)
    std::swap(SignExtendingValue, Zero);

  // If we should not perform sign-extension then we must add/or/subtract zero.
  if (!match(Zero, m_Zero()))
    return nullptr;
  // Otherwise, it should be some constant, left-shifted by the same NBits we
  // had in `lshr`. Said left-shift can also be appropriately extended.
  // Again, we must look past zero-ext when looking for NBits.
  SkipExtInMagic(SignExtendingValue);
  Constant *SignExtendingValueBaseConstant;
  if (!match(SignExtendingValue,
             m_Shl(m_Constant(SignExtendingValueBaseConstant),
                   m_ZExtOrSelf(m_Specific(NBits)))))
    return nullptr;
  // If we `sub`, then the constant should be one, else it should be all-ones.
  if (I.getOpcode() == Instruction::Sub
          ? !match(SignExtendingValueBaseConstant, m_One())
          : !match(SignExtendingValueBaseConstant, m_AllOnes()))
    return nullptr;

  auto *NewAShr = BinaryOperator::CreateAShr(X, LowBitsToSkip,
                                             Extract->getName() + ".sext");
  NewAShr->copyIRFlags(Extract); // Preserve `exact`-ness.
  if (!HadTrunc)
    return NewAShr;

  Builder.Insert(NewAShr);
  return TruncInst::CreateTruncOrBitCast(NewAShr, I.getType());
}

Value *InstCombinerImpl::OptimizePointerDifference(Value *LHS, Value *RHS,
                                                   Type *Ty, bool IsNUW) {
  CommonPointerBase Base = CommonPointerBase::compute(LHS, RHS);
  if (!Base.Ptr || Base.isExpensive())
    return nullptr;

  // To avoid duplicating the offset arithmetic, rewrite the GEP to use the
  // computed offset.
  // TODO: We should probably do this even if there is only one GEP.
  bool RewriteGEPs = !Base.LHSGEPs.empty() && !Base.RHSGEPs.empty();

  Type *IdxTy = DL.getIndexType(LHS->getType());
  Value *Result = EmitGEPOffsets(Base.LHSGEPs, Base.LHSNW, IdxTy, RewriteGEPs);
  Value *Offset2 = EmitGEPOffsets(Base.RHSGEPs, Base.RHSNW, IdxTy, RewriteGEPs);

  // If this is a single inbounds GEP and the original sub was nuw,
  // then the final multiplication is also nuw.
  if (auto *I = dyn_cast<OverflowingBinaryOperator>(Result))
    if (IsNUW && match(Offset2, m_Zero()) && Base.LHSNW.isInBounds() &&
        (I->use_empty() || I->hasOneUse()) && I->hasNoSignedWrap() &&
        !I->hasNoUnsignedWrap() &&
        ((I->getOpcode() == Instruction::Mul &&
          match(I->getOperand(1), m_NonNegative())) ||
         I->getOpcode() == Instruction::Shl))
      cast<Instruction>(I)->setHasNoUnsignedWrap();

  // If we have a 2nd GEP of the same base pointer, subtract the offsets.
  // If both GEPs are inbounds, then the subtract does not have signed overflow.
  // If both GEPs are nuw and the original sub is nuw, the new sub is also nuw.
  if (!match(Offset2, m_Zero())) {
    Result =
        Builder.CreateSub(Result, Offset2, "gepdiff",
                          IsNUW && Base.LHSNW.hasNoUnsignedWrap() &&
                              Base.RHSNW.hasNoUnsignedWrap(),
                          Base.LHSNW.isInBounds() && Base.RHSNW.isInBounds());
  }

  return Builder.CreateIntCast(Result, Ty, true);
}

if (match(Op0, m_Not(m_Value(X))) &&
    match(Op1, m_c_MaxOrMin(m_Specific(Op0), m_Value(Y))) &&
    !Op0->hasNUsesOrMore(3) && isFreeToInvert(Y, Y->hasOneUse())) {
  Value *Not = Builder.CreateNot(Op1);
  return BinaryOperator::CreateSub(Not, X);

if (match(Op1, m_Not(m_Value(X))) &&
    match(Op0, m_c_MaxOrMin(m_Specific(Op1), m_Value(Y))) &&
    !Op1->hasNUsesOrMore(3) && isFreeToInvert(Y, Y->hasOneUse())) {
  Value *Not = Builder.CreateNot(Op0);
  return BinaryOperator::CreateSub(X, Not);

auto MatchSubOfZExtOfPtrToIntOrAddr = [&]() {
  if (match(Op0, m_ZExt(m_PtrToIntSameSize(DL, m_Value(LHSOp)))) &&
      match(Op1, m_ZExt(m_PtrToIntSameSize(DL, m_Value(RHSOp)))))
    return true;
  if (match(Op0, m_ZExt(m_PtrToAddr(m_Value(LHSOp)))) &&
      match(Op1, m_ZExt(m_PtrToAddr(m_Value(RHSOp)))))
    return true;
  // Special case for non-canonical ptrtoint in constant expression,
  // where the zext has been folded into the ptrtoint.
  if (match(Op0, m_ZExt(m_PtrToIntSameSize(DL, m_Value(LHSOp)))) &&
      match(Op1, m_PtrToInt(m_Value(RHSOp))))
    return true;
  return false;
};
if (MatchSubOfZExtOfPtrToIntOrAddr()) {
  if (auto *GEP = dyn_cast<GEPOperator>(LHSOp)) {
    if (GEP->getPointerOperand() == RHSOp) {
      if (GEP->hasNoUnsignedWrap() || GEP->hasNoUnsignedSignedWrap()) {
        Value *Offset = EmitGEPOffset(GEP);
        Value *Res = GEP->hasNoUnsignedWrap()
                         ? Builder.CreateZExt(
                               Offset, I.getType(), "",
                               /*IsNonNeg=*/GEP->hasNoUnsignedSignedWrap())
                         : Builder.CreateSExt(Offset, I.getType());
        return replaceInstUsesWith(I, Res);
      }
    }

      Builder.CreateFNegFMF(X, &FMFSource), Y, &FMFSource));
  FDiv->copyMetadata(*cast<Instruction>(FNegOp));
  return FDiv;
}

if (IntrinsicInst *II = dyn_cast<IntrinsicInst>(FNegOp)) {
  // Make sure to preserve flags and metadata on the call.

// Make sure the LHS/RHS compare a part of the same value, possibly after
// an operand swap.
if (L0->From != L1->From || R0->From != R1->From) {
  if (L0->From != R1->From || R0->From != L1->From)
    return nullptr;
  std::swap(L1, R1);
}

// Make sure the extracted parts are adjacent, canonicalizing to L0/R0 being
// the low part and L1/R1 being the high part.
if (L0->StartBit + L0->NumBits != L1->StartBit ||
    R0->StartBit + R0->NumBits != R1->StartBit) {
  if (L1->StartBit + L1->NumBits != L0->StartBit ||
      R1->StartBit + R1->NumBits != R0->StartBit)
    return nullptr;
  std::swap(L0, L1);
  std::swap(R0, R1);
}

// We can simplify to a comparison of these larger parts of the integers.
IntPart L = {L0->From, L0->StartBit, L0->NumBits + L1->NumBits};
IntPart R = {R0->From, R0->StartBit, R0->NumBits + R1->NumBits};
Value *LValue = extractIntPart(L, Builder);
Value *RValue = extractIntPart(R, Builder);
return Builder.CreateICmp(Pred, LValue, RValue);

// Replace variable with constant value equivalence to remove a variable use:
// (X == C) && (Y Pred1 X) --> (X == C) && (Y Pred1 C)
// (X != C) || (Y Pred1 X) --> (X != C) || (Y Pred1 C)
// Can think of the 'or' substitution with the 'and' bool equivalent:
// A || B --> A || (!A && B)
Value *SubstituteCmp = simplifyICmpInst(PredR, Y, LHS1, Q);
if (!SubstituteCmp) {
  // If we need to create a new instruction, require that the old compare can
  // be removed.
  if (!RHSOneUse)
    return nullptr;
  SubstituteCmp = Builder.CreateICmp(PredR, Y, LHS1);
}
if (IsLogical) {
  Instruction *MDFrom = isa<SelectInst>(I) ? &I : nullptr;
  return IsAnd ? Builder.CreateLogicalAnd(LHS, SubstituteCmp, "", MDFrom)
               : Builder.CreateLogicalOr(LHS, SubstituteCmp, "", MDFrom);

Value *NotC = Op1->hasOneUse()
                  ? Builder.CreateNot(C)
                  : getFreelyInverted(C, C->hasOneUse(), &Builder);
if (NotC != nullptr)
  return BinaryOperator::CreateAnd(Op0, NotC);

Value *NotC = Op0->hasOneUse()
                  ? Builder.CreateNot(C)
                  : getFreelyInverted(C, C->hasOneUse(), &Builder);
if (NotC != nullptr)
  return BinaryOperator::CreateAnd(Op1, NotC);

if (Value *Cond = getSelectCondition(A, C, InvertFalseVal)) {
  // ((bc Cond) & B) | ((bc ~Cond) & D) --> bc (select Cond, (bc B), (bc D))
  // If this is a vector, we may need to cast to match the condition's length.
  // The bitcasts will either all exist or all not exist. The builder will
  // not create unnecessary casts if the types already match.
  Type *SelTy = A->getType();
  if (auto *VecTy = dyn_cast<VectorType>(Cond->getType())) {
    // For a fixed or scalable vector get N from <{vscale x} N x iM>
    unsigned Elts = VecTy->getElementCount().getKnownMinValue();
    // For a fixed or scalable vector, get the size in bits of N x iM; for a
    // scalar this is just M.
    unsigned SelEltSize = SelTy->getPrimitiveSizeInBits().getKnownMinValue();
    Type *EltTy = Builder.getIntNTy(SelEltSize / Elts);
    SelTy = VectorType::get(EltTy, VecTy->getElementCount());
  }
  Value *BitcastB = Builder.CreateBitCast(B, SelTy);
  if (InvertFalseVal)
    D = Builder.CreateNot(D);
  Value *BitcastD = Builder.CreateBitCast(D, SelTy);
  // The condition here is synthesized and thus we have no way of knowing the
  // distribution in general. Thus, mark the branch weights of the created
  // select unknown.
  Value *Select = Builder.CreateSelectWithUnknownProfile(
      Cond, BitcastB, BitcastD, DEBUG_TYPE);
  return Builder.CreateBitCast(Select, OrigType);

return Builder.CreateICmp(
    IsAnd ? ICmpInst::ICMP_ULT : ICmpInst::ICMP_UGE,
    Builder.CreateSub(LHS0, ConstantInt::get(LHS0->getType(), *CInt + 1)),
    Other);

if (Value *OrICmp = simplifyBinOp(Instruction::Or, LHS, RHS, SQ)) {
  // TODO: If OrICmp is true, then the definition of xor simplifies to !(X&Y).
  // TODO: If OrICmp is false, the whole thing is false (InstSimplify?).
  if (Value *AndICmp = simplifyBinOp(Instruction::And, LHS, RHS, SQ)) {
    // TODO: Independently handle cases where the 'and' side is a constant.
    ICmpInst *X = nullptr, *Y = nullptr;
    if (OrICmp == LHS && AndICmp == RHS) {
      // (LHS | RHS) & !(LHS & RHS) --> LHS & !RHS  --> X & !Y
      X = LHS;
      Y = RHS;
    }
    if (OrICmp == RHS && AndICmp == LHS) {
      // !(LHS & RHS) & (LHS | RHS) --> !LHS & RHS  --> !Y & X
      X = RHS;
      Y = LHS;
    }
    if (X && Y && (Y->hasOneUse() || canFreelyInvertAllUsersOf(Y, &I))) {
      // Invert the predicate of 'Y', thus inverting its output.
      Y->setPredicate(Y->getInversePredicate());
      // So, are there other uses of Y?
      if (!Y->hasOneUse()) {
        // We need to adapt other uses of Y though. Get a value that matches
        // the original value of Y before inversion. While this increases
        // immediate instruction count, we have just ensured that all the
        // users are freely-invertible, so that 'not' *will* get folded away.
        BuilderTy::InsertPointGuard Guard(Builder);
        // Set insertion point to right after the Y.
        Builder.SetInsertPoint(++(Y->getIterator()));
        Value *NotY = Builder.CreateNot(Y, Y->getName() + ".not");
        // Replace all uses of Y (excluding the one in NotY!) with NotY.
        Worklist.pushUsersToWorkList(*Y);
        Y->replaceUsesWithIf(NotY,
                             [NotY](Use &U) { return U.getUser() != NotY; });
      }
      // All done.
      return Builder.CreateAnd(LHS, RHS);

if (Value *OrICmp = simplifyBinOp(Instruction::Or, LHS, RHS, SQ)) {
  // TODO: If OrICmp is true, then the definition of xor simplifies to !(X&Y).
  // TODO: If OrICmp is false, the whole thing is false (InstSimplify?).
  if (Value *AndICmp = simplifyBinOp(Instruction::And, LHS, RHS, SQ)) {
    // TODO: Independently handle cases where the 'and' side is a constant.
    ICmpInst *X = nullptr, *Y = nullptr;
    if (OrICmp == LHS && AndICmp == RHS) {
      // (LHS | RHS) & !(LHS & RHS) --> LHS & !RHS  --> X & !Y
      X = LHS;
      Y = RHS;
    }
    if (OrICmp == RHS && AndICmp == LHS) {
      // !(LHS & RHS) & (LHS | RHS) --> !LHS & RHS  --> !Y & X
      X = RHS;
      Y = LHS;
    }
    if (X && Y && (Y->hasOneUse() || canFreelyInvertAllUsersOf(Y, &I))) {
      // Invert the predicate of 'Y', thus inverting its output.
      Y->setPredicate(Y->getInversePredicate());
      // So, are there other uses of Y?
      if (!Y->hasOneUse()) {
        // We need to adapt other uses of Y though. Get a value that matches
        // the original value of Y before inversion. While this increases
        // immediate instruction count, we have just ensured that all the
        // users are freely-invertible, so that 'not' *will* get folded away.
        BuilderTy::InsertPointGuard Guard(Builder);
        // Set insertion point to right after the Y.
        Builder.SetInsertPoint(++(Y->getIterator()));
        Value *NotY = Builder.CreateNot(Y, Y->getName() + ".not");
        // Replace all uses of Y (excluding the one in NotY!) with NotY.
        Worklist.pushUsersToWorkList(*Y);
        Y->replaceUsesWithIf(NotY,
                             [NotY](Use &U) { return U.getUser() != NotY; });
      }
      // All done.
      return Builder.CreateAnd(LHS, RHS);

if (match(NotOp, m_OneUse(m_BitCast(m_Value(X)))) &&
    match(X, m_OneUse(m_Cmp(Pred, m_Value(), m_Value())))) {
  cast<CmpInst>(X)->setPredicate(CmpInst::getInversePredicate(Pred));
  return new BitCastInst(X, Ty);

// If MemCpyInst length is 1/2/4/8 bytes then replace memcpy with
// load/store.
ConstantInt *MemOpLength = dyn_cast<ConstantInt>(MI->getLength());
if (!MemOpLength) return nullptr;

// Source and destination pointer types are always "i8*" for intrinsic.  See
// if the size is something we can handle with a single primitive load/store.
// A single load+store correctly handles overlapping memory in the memmove
// case.
uint64_t Size = MemOpLength->getLimitedValue();
assert(Size && "0-sized memory transferring should be removed already.");

if (Size > 8 || (Size&(Size-1)))
  return nullptr;  // If not 1/2/4/8 bytes, exit.

// If it is an atomic and alignment is less than the size then we will
// introduce the unaligned memory access which will be later transformed
// into libcall in CodeGen. This is not evident performance gain so disable
// it now.
if (MI->isAtomic())
  if (*CopyDstAlign < Size || *CopySrcAlign < Size)
    return nullptr;

// Use an integer load+store unless we can find something better.
IntegerType* IntType = IntegerType::get(MI->getContext(), Size<<3);

// If the memcpy has metadata describing the members, see if we can get the
// TBAA, scope and noalias tags describing our copy.
AAMDNodes AACopyMD = MI->getAAMetadata().adjustForAccess(Size);

Value *Src = MI->getArgOperand(1);
Value *Dest = MI->getArgOperand(0);
LoadInst *L = Builder.CreateLoad(IntType, Src);
// Alignment from the mem intrinsic will be better, so use it.
L->setAlignment(*CopySrcAlign);
L->setAAMetadata(AACopyMD);
MDNode *LoopMemParallelMD =
  MI->getMetadata(LLVMContext::MD_mem_parallel_loop_access);
if (LoopMemParallelMD)
  L->setMetadata(LLVMContext::MD_mem_parallel_loop_access, LoopMemParallelMD);
MDNode *AccessGroupMD = MI->getMetadata(LLVMContext::MD_access_group);
if (AccessGroupMD)
  L->setMetadata(LLVMContext::MD_access_group, AccessGroupMD);

StoreInst *S = Builder.CreateStore(L, Dest);
// Alignment from the mem intrinsic will be better, so use it.
S->setAlignment(*CopyDstAlign);
S->setAAMetadata(AACopyMD);
if (LoopMemParallelMD)
  S->setMetadata(LLVMContext::MD_mem_parallel_loop_access, LoopMemParallelMD);
if (AccessGroupMD)
  S->setMetadata(LLVMContext::MD_access_group, AccessGroupMD);
S->copyMetadata(*MI, LLVMContext::MD_DIAssignID);

if (auto *MT = dyn_cast<MemTransferInst>(MI)) {
  // non-atomics can be volatile
  L->setVolatile(MT->isVolatile());
  S->setVolatile(MT->isVolatile());
}
if (MI->isAtomic()) {
  // atomics have to be unordered
  L->setOrdering(AtomicOrdering::Unordered);
  S->setOrdering(AtomicOrdering::Unordered);
}

// Set the size of the copy to 0, it will be deleted on the next iteration.
MI->setLength((uint64_t)0);
return MI;

// Extract the length and validate the fill type.
ConstantInt *LenC = dyn_cast<ConstantInt>(MI->getLength());
Value *Fill = MI->getValue();
if (!LenC || !Fill->getType()->isIntegerTy(8))
  return nullptr;
const uint64_t Len = LenC->getLimitedValue();
assert(Len && "0-sized memory setting should be removed already.");
const Align Alignment = MI->getDestAlign().valueOrOne();

// If it is an atomic and alignment is less than the size then we will
// introduce the unaligned memory access which will be later transformed
// into libcall in CodeGen. This is not evident performance gain so disable
// it now.
if (MI->isAtomic() && Alignment < Len)
  return nullptr;

// memset(s,c,n) -> store s, c (for n=1,2,4,8)
if (Len <= 8 && isPowerOf2_32((uint32_t)Len)) {
  Value *Dest = MI->getDest();

  // Extract the fill value and store.  A one-byte memset does not need
  // replication so a nonconstant i8 fill can be stored directly.
  Value *FillVal;
  if (auto *FillC = dyn_cast<ConstantInt>(Fill))
    FillVal = ConstantInt::get(MI->getContext(),
                               APInt::getSplat(Len * 8, FillC->getValue()));
  else if (Len == 1)
    FillVal = Fill;
  else
    return nullptr;

  StoreInst *S = Builder.CreateStore(FillVal, Dest, MI->isVolatile());
  S->copyMetadata(*MI, LLVMContext::MD_DIAssignID);
  for (DbgVariableRecord *DbgAssign : at::getDVRAssignmentMarkers(S)) {
    if (llvm::is_contained(DbgAssign->location_ops(), Fill))
      DbgAssign->replaceVariableLocationOp(Fill, FillVal);
  }

  S->setAlignment(Alignment);
  if (MI->isAtomic())
    S->setOrdering(AtomicOrdering::Unordered);

  // Set the size of the copy to 0, it will be deleted on the next iteration.
  MI->setLength((uint64_t)0);
  return MI;

// Vector splat address w/known mask -> scalar load
// Fold the gather to load the source vector first lane
// because it is reloading the same value each time
if (ConstMask->isAllOnesValue())
  if (auto *SplatPtr = getSplatValue(II.getArgOperand(0))) {
    auto *VecTy = cast<VectorType>(II.getType());
    const Align Alignment = II.getParamAlign(0).valueOrOne();
    LoadInst *L = Builder.CreateAlignedLoad(VecTy->getElementType(), SplatPtr,
                                            Alignment, "load.scalar");
    Value *Shuf =
        Builder.CreateVectorSplat(VecTy->getElementCount(), L, "broadcast");
    return replaceInstUsesWith(II, cast<Instruction>(Shuf));

// cttz(Pow2) -> Log2(Pow2)
// ctlz(Pow2) -> BitWidth - 1 - Log2(Pow2)
if (auto *R = IC.tryGetLog2(Op0, match(Op1, m_One()))) {
  if (IsTZ)
    return IC.replaceInstUsesWith(II, R);
  BinaryOperator *BO = BinaryOperator::CreateSub(
      ConstantInt::get(R->getType(), R->getType()->getScalarSizeInBits() - 1),
      R);
  BO->setHasNoSignedWrap();
  BO->setHasNoUnsignedWrap();
  return BO;
}

IRBuilderBase &B = IC.Builder;
if (AllPositive)
  return IC.replaceInstUsesWith(*II, B.CreateShl(Arg0, ShiftConst));

Value *NegAmt = B.CreateNeg(ShiftConst);
Intrinsic::ID IID = II->getIntrinsicID();
const bool IsSigned =
    IID == Intrinsic::arm_neon_vshifts || IID == Intrinsic::aarch64_neon_sshl;
Value *Result =
    IsSigned ? B.CreateAShr(Arg0, NegAmt) : B.CreateLShr(Arg0, NegAmt);
return IC.replaceInstUsesWith(*II, Result);

// If C is not 0:
//   umax(nuw_shl(x, C), x + 1) -> x == 0 ? 1 : nuw_shl(x, C)
// If C is not 0 or 1:
//   umax(nuw_mul(x, C), x + 1) -> x == 0 ? 1 : nuw_mul(x, C)
auto foldMaxMulShift = [&](Value *A, Value *B) -> Instruction * {
  const APInt *C;
  Value *X;
  if (!match(A, m_NUWShl(m_Value(X), m_APInt(C))) &&
      !(match(A, m_NUWMul(m_Value(X), m_APInt(C))) && !C->isOne()))
    return nullptr;
  if (C->isZero())
    return nullptr;
  if (!match(B, m_OneUse(m_Add(m_Specific(X), m_One()))))
    return nullptr;

  Value *Cmp = Builder.CreateICmpEQ(X, ConstantInt::get(X->getType(), 0));
  Value *NewSelect = nullptr;
  NewSelect = Builder.CreateSelectWithUnknownProfile(
      Cmp, ConstantInt::get(X->getType(), 1), A, DEBUG_TYPE);
  return replaceInstUsesWith(*II, NewSelect);
};

if (IID == Intrinsic::umax) {
  if (Instruction *I = foldMaxMulShift(I0, I1))
    return I;
  if (Instruction *I = foldMaxMulShift(I1, I0))
    return I;
}

if (ConstantFP *Base = dyn_cast<ConstantFP>(II->getArgOperand(0))) {
  Value *Exp = II->getArgOperand(1);
  Type *Ty = Base->getType();
  // powi(2.0, p) -> ldexp(1.0, p)
  if (II->hasApproxFunc() && Base->isExactlyValue(2.0)) {
    ConstantFP *One = ConstantFP::get(Ty, 1.0);
    if (auto *VTy = dyn_cast<VectorType>(Ty))
      Exp = Builder.CreateVectorSplat(VTy->getElementCount(), Exp);
    Value *Ldexp = Builder.CreateLdexp(One, Exp, II);
    return replaceInstUsesWith(*II, Ldexp);
  }

Value *InnerPtr, *InnerMask;
bool Changed = false;
// Combine:
// (ptrmask (ptrmask p, A), B)
//    -> (ptrmask p, (and A, B))
if (match(II->getArgOperand(0),
          m_OneUse(m_Intrinsic<Intrinsic::ptrmask>(m_Value(InnerPtr),
                                                   m_Value(InnerMask))))) {
  assert(II->getArgOperand(1)->getType() == InnerMask->getType() &&
         "Mask types must match");
  // TODO: If InnerMask == Op1, we could copy attributes from inner
  // callsite -> outer callsite.
  Value *NewMask = Builder.CreateAnd(II->getArgOperand(1), InnerMask);
  replaceOperand(CI, 0, InnerPtr);
  replaceOperand(CI, 1, NewMask);
  Changed = true;

if (ElementCount::isKnownGT(NegatedCount, OtherCount) &&
    ElementCount::isKnownLT(OtherCount, RetCount)) {
  Value *InverseOtherOp = Builder.CreateFNeg(OtherOp);
  replaceOperand(*II, NegatedOpArg, OpNotNeg);
  replaceOperand(*II, OtherOpArg, InverseOtherOp);
  return II;

case BundleAttr::NonNull: {
  auto [Ptr] = llvm::getAssumeNonNullInfo(OBU);

  // Drop assume if we can prove nonnull without it
  if (isKnownNonZero(Ptr, getSimplifyQuery().getWithInstruction(II)))
    return RemoveBundle();

  // Fold the assume into metadata if it's valid at the load
  if (auto *LI = dyn_cast<LoadInst>(Ptr);
      LI &&
      isValidAssumeForContext(II, LI, &DT, /*AllowEphemerals=*/true)) {
    MDNode *MD = MDNode::get(II->getContext(), {});
    LI->setMetadata(LLVMContext::MD_nonnull, MD);
    LI->setMetadata(LLVMContext::MD_noundef, MD);
    return RemoveBundle();
  }

  if (auto *GEP = dyn_cast<GEPOperator>(Ptr);
      GEP && GEP->isInBounds() &&
      !NullPointerIsDefined(II->getFunction(),
                            Ptr->getType()->getPointerAddressSpace())) {
    Builder.CreateNonnullAssumption(GEP->stripInBoundsOffsets());
    return RemoveBundle();
  }

case Intrinsic::experimental_guard: {
  // Is this guard followed by another guard?  We scan forward over a small
  // fixed window of instructions to handle common cases with conditions
  // computed between guards.
  Instruction *NextInst = II->getNextNode();
  for (unsigned i = 0; i < CLOpts.guard_widening_window; i++) {
    // Note: Using context-free form to avoid compile time blow up
    if (!isSafeToSpeculativelyExecute(NextInst))
      break;
    NextInst = NextInst->getNextNode();
  }
  Value *NextCond = nullptr;
  if (match(NextInst,
            m_Intrinsic<Intrinsic::experimental_guard>(m_Value(NextCond)))) {
    Value *CurrCond = II->getArgOperand(0);

    // Remove a guard that it is immediately preceded by an identical guard.
    // Otherwise canonicalize guard(a); guard(b) -> guard(a & b).
    if (CurrCond != NextCond) {
      Instruction *MoveI = II->getNextNode();
      while (MoveI != NextInst) {
        auto *Temp = MoveI;
        MoveI = MoveI->getNextNode();
        Temp->moveBefore(II->getIterator());
      }
      replaceOperand(*II, 0, Builder.CreateAnd(CurrCond, NextCond));
    }
    eraseInstFromFunction(*NextInst);
    return II;
  }

// If the call and callee calling conventions don't match, and neither one
// of the calling conventions is compatible with C calling convention
// this call must be unreachable, as the call is undefined.
if ((CalleeF->getCallingConv() != Call.getCallingConv() &&
     !(CalleeF->getCallingConv() == llvm::CallingConv::C &&
       TargetLibraryInfoImpl::isCallingConvCCompatible(&Call)) &&
     !(Call.getCallingConv() == llvm::CallingConv::C &&
       TargetLibraryInfoImpl::isCallingConvCCompatible(CalleeF))) &&
    // Only do this for calls to a function with a body.  A prototype may
    // not actually end up matching the implementation's calling conv for a
    // variety of reasons (e.g. it may be written in assembly).
    !CalleeF->isDeclaration()) {
  Instruction *OldCall = &Call;
  CreateNonTerminatorUnreachable(OldCall);
  // If OldCall does not return void then replaceInstUsesWith poison.
  // This allows ValueHandlers and custom metadata to adjust itself.
  if (!OldCall->getType()->isVoidTy())
    replaceInstUsesWith(*OldCall, PoisonValue::get(OldCall->getType()));
  if (isa<CallInst>(OldCall))
    return eraseInstFromFunction(*OldCall);

  // We cannot remove an invoke or a callbr, because it would change thexi
  // CFG, just change the callee to a null pointer.
  cast<CallBase>(OldCall)->setCalledFunction(
      CalleeF->getFunctionType(),
      Constant::getNullValue(CalleeF->getType()));
  return nullptr;

// Calling a null function pointer is undefined if a null address isn't
// dereferenceable.
if ((isa<ConstantPointerNull>(Callee) &&
     !NullPointerIsDefined(Call.getFunction())) ||
    isa<UndefValue>(Callee)) {
  // If Call does not return void then replaceInstUsesWith poison.
  // This allows ValueHandlers and custom metadata to adjust itself.
  if (!Call.getType()->isVoidTy())
    replaceInstUsesWith(Call, PoisonValue::get(Call.getType()));

  if (Call.isTerminator()) {
    // Can't remove an invoke or callbr because we cannot change the CFG.
    return nullptr;
  }

  // This instruction is not reachable, just remove it.
  CreateNonTerminatorUnreachable(&Call);
  return eraseInstFromFunction(Call);
}

Instruction *InstCombinerImpl::narrowFunnelShift(TruncInst &Trunc) {
  assert((isa<VectorType>(Trunc.getSrcTy()) ||
          shouldChangeType(Trunc.getSrcTy(), Trunc.getType())) &&
         "Don't narrow to an illegal scalar type");

  // Bail out on strange types. It is possible to handle some of these patterns
  // even with non-power-of-2 sizes, but it is not a likely scenario.
  Type *DestTy = Trunc.getType();
  unsigned NarrowWidth = DestTy->getScalarSizeInBits();
  unsigned WideWidth = Trunc.getSrcTy()->getScalarSizeInBits();
  if (!isPowerOf2_32(NarrowWidth))
    return nullptr;

  // First, find an or'd pair of opposite shifts:
  // trunc (or (lshr ShVal0, ShAmt0), (shl ShVal1, ShAmt1))
  BinaryOperator *Or0, *Or1;
  if (!match(Trunc.getOperand(0), m_OneUse(m_Or(m_BinOp(Or0), m_BinOp(Or1)))))
    return nullptr;

  Value *ShVal0, *ShVal1, *ShAmt0, *ShAmt1;
  if (!match(Or0, m_OneUse(m_LogicalShift(m_Value(ShVal0), m_Value(ShAmt0)))) ||
      !match(Or1, m_OneUse(m_LogicalShift(m_Value(ShVal1), m_Value(ShAmt1)))) ||
      Or0->getOpcode() == Or1->getOpcode())
    return nullptr;

  // Canonicalize to or(shl(ShVal0, ShAmt0), lshr(ShVal1, ShAmt1)).
  if (Or0->getOpcode() == BinaryOperator::LShr) {
    std::swap(Or0, Or1);
    std::swap(ShVal0, ShVal1);
    std::swap(ShAmt0, ShAmt1);
  }
  assert(Or0->getOpcode() == BinaryOperator::Shl &&
         Or1->getOpcode() == BinaryOperator::LShr &&
         "Illegal or(shift,shift) pair");

  // Match the shift amount operands for a funnel/rotate pattern. This always
  // matches a subtraction on the R operand.
  auto matchShiftAmount = [&](Value *L, Value *R, unsigned Width) -> Value * {
    // The shift amounts may add up to the narrow bit width:
    // (shl ShVal0, L) | (lshr ShVal1, Width - L)
    // If this is a funnel shift (different operands are shifted), then the
    // shift amount can not over-shift (create poison) in the narrow type.
    unsigned MaxShiftAmountWidth = Log2_32(NarrowWidth);
    APInt HiBitMask = ~APInt::getLowBitsSet(WideWidth, MaxShiftAmountWidth);
    if (ShVal0 == ShVal1 || MaskedValueIsZero(L, HiBitMask))
      if (match(R, m_OneUse(m_Sub(m_SpecificInt(Width), m_Specific(L)))))
        return L;

    // The following patterns currently only work for rotation patterns.
    // TODO: Add more general funnel-shift compatible patterns.
    if (ShVal0 != ShVal1)
      return nullptr;

    // The shift amount may be masked with negation:
    // (shl ShVal0, (X & (Width - 1))) | (lshr ShVal1, ((-X) & (Width - 1)))
    Value *X;
    unsigned Mask = Width - 1;
    if (match(L, m_And(m_Value(X), m_SpecificInt(Mask))) &&
        match(R, m_And(m_Neg(m_Specific(X)), m_SpecificInt(Mask))))
      return X;

    // Same as above, but the shift amount may be extended after masking:
    if (match(L, m_ZExt(m_And(m_Value(X), m_SpecificInt(Mask)))) &&
        match(R, m_ZExt(m_And(m_Neg(m_Specific(X)), m_SpecificInt(Mask)))))
      return X;

    return nullptr;
  };

  Value *ShAmt = matchShiftAmount(ShAmt0, ShAmt1, NarrowWidth);
  bool IsFshl = true; // Sub on LSHR.
  if (!ShAmt) {
    ShAmt = matchShiftAmount(ShAmt1, ShAmt0, NarrowWidth);
    IsFshl = false; // Sub on SHL.
  }
  if (!ShAmt)
    return nullptr;

  // The right-shifted value must have high zeros in the wide type (for example
  // from 'zext', 'and' or 'shift'). High bits of the left-shifted value are
  // truncated, so those do not matter.
  APInt HiBitMask = APInt::getHighBitsSet(WideWidth, WideWidth - NarrowWidth);
  if (!MaskedValueIsZero(ShVal1, HiBitMask, &Trunc))
    return nullptr;

  // Adjust the width of ShAmt for narrowed funnel shift operation:
  // - Zero-extend if ShAmt is narrower than the destination type.
  // - Truncate if ShAmt is wider, discarding non-significant high-order bits.
  // This prepares ShAmt for llvm.fshl.i8(trunc(ShVal), trunc(ShVal),
  // zext/trunc(ShAmt)).
  Value *NarrowShAmt = Builder.CreateZExtOrTrunc(ShAmt, DestTy);

  Value *X, *Y;
  X = Y = Builder.CreateTrunc(ShVal0, DestTy);
  if (ShVal0 != ShVal1)
    Y = Builder.CreateTrunc(ShVal1, DestTy);
  Intrinsic::ID IID = IsFshl ? Intrinsic::fshl : Intrinsic::fshr;
  Function *F =
      Intrinsic::getOrInsertDeclaration(Trunc.getModule(), IID, DestTy);
  return CallInst::Create(F, {X, Y, NarrowShAmt});

  break;
}
case Instruction::LShr:
case Instruction::AShr: {
  // trunc (*shr (trunc A), C) --> trunc(*shr A, C)
  Value *A;
  Constant *C;
  if (match(BinOp0, m_Trunc(m_Value(A))) && match(BinOp1, m_Constant(C))) {
    unsigned MaxShiftAmt = SrcWidth - DestWidth;
    // If the shift is small enough, all zero/sign bits created by the shift
    // are removed by the trunc.
    if (match(C, m_SpecificInt_ICMP(ICmpInst::ICMP_ULE,
                                    APInt(SrcWidth, MaxShiftAmt)))) {
      auto *OldShift = cast<Instruction>(Trunc.getOperand(0));
      bool IsExact = OldShift->isExact();
      if (Constant *ShAmt = ConstantFoldIntegerCast(C, A->getType(),
                                                    /*IsSigned*/ true, DL)) {
        ShAmt = Constant::mergeUndefsWith(ShAmt, C);
        Value *Shift =
            OldShift->getOpcode() == Instruction::AShr
                ? Builder.CreateAShr(A, ShAmt, OldShift->getName(), IsExact)
                : Builder.CreateLShr(A, ShAmt, OldShift->getName(), IsExact);
        return CastInst::CreateTruncOrBitCast(Shift, DestTy);

// width may enable further optimizations, e.g. allowing for larger
// vectorization factors.
if (auto *DestITy = dyn_cast<IntegerType>(DestTy)) {
  if (DestWidth * 2 < SrcWidth) {
    auto *NewDestTy = DestITy->getExtendedType();
    if (shouldChangeType(SrcTy, NewDestTy) &&
        TypeEvaluationHelper::canEvaluateTruncated(Src, NewDestTy, *this,
                                                   &Trunc)) {
      LLVM_DEBUG(
          dbgs() << "ICE: EvaluateInDifferentType converting expression type"
                    " to reduce the width of operand of"
                 << Trunc << '\n');
      Value *Res = EvaluateInDifferentType(Src, NewDestTy, false);
      return new TruncInst(Res, DestTy);

                 : BinaryOperator::CreateAShr(A, ShAmt);
}
// The types are mismatched, so create a cast after shifting:
// trunc (lshr (sext A), C) --> sext/trunc (ashr A, C)
if (Src->hasOneUse()) {
  Constant *ShAmt = GetNewShAmt(AWidth);
  Value *Shift = Builder.CreateAShr(A, ShAmt, "", IsExact);
  return CastInst::CreateIntegerCast(Shift, DestTy, true);

Instruction *InstCombinerImpl::transformZExtICmp(ICmpInst *Cmp,
                                                 ZExtInst &Zext) {
  // If we are just checking for a icmp eq of a single bit and zext'ing it
  // to an integer, then shift the bit to the appropriate place and then
  // cast to integer to avoid the comparison.

  // FIXME: This set of transforms does not check for extra uses and/or creates
  //        an extra instruction (an optional final cast is not included
  //        in the transform comments). We may also want to favor icmp over
  //        shifts in cases of equal instructions because icmp has better
  //        analysis in general (invert the transform).

  const APInt *Op1CV;
  if (match(Cmp->getOperand(1), m_APInt(Op1CV))) {

    // zext (x <s  0) to i32 --> x>>u31      true if signbit set.
    if (Cmp->getPredicate() == ICmpInst::ICMP_SLT && Op1CV->isZero()) {
      Value *In = Cmp->getOperand(0);
      Value *Sh = ConstantInt::get(In->getType(),
                                   In->getType()->getScalarSizeInBits() - 1);
      In = Builder.CreateLShr(In, Sh, In->getName() + ".lobit");
      if (In->getType() != Zext.getType())
        In = Builder.CreateIntCast(In, Zext.getType(), false /*ZExt*/);

      return replaceInstUsesWith(Zext, In);

// zext (X == 0) to i32 --> X^1      iff X has only the low bit set.
// zext (X == 0) to i32 --> (X>>1)^1 iff X has only the 2nd bit set.
// zext (X != 0) to i32 --> X        iff X has only the low bit set.
// zext (X != 0) to i32 --> X>>1     iff X has only the 2nd bit set.

if (Op1CV->isZero() && Cmp->isEquality()) {
  // Exactly 1 possible 1? But not the high-bit because that is
  // canonicalized to this form.
  KnownBits Known = computeKnownBits(Cmp->getOperand(0), &Zext);
  APInt KnownZeroMask(~Known.Zero);
  uint32_t ShAmt = KnownZeroMask.logBase2();
  bool IsExpectShAmt = KnownZeroMask.isPowerOf2() &&
                       (Zext.getType()->getScalarSizeInBits() != ShAmt + 1);
  if (IsExpectShAmt &&
      (Cmp->getOperand(0)->getType() == Zext.getType() ||
       Cmp->getPredicate() == ICmpInst::ICMP_NE || ShAmt == 0)) {
    Value *In = Cmp->getOperand(0);
    if (ShAmt) {
      // Perform a logical shr by shiftamt.
      // Insert the shift to put the result in the low bit.
      In = Builder.CreateLShr(In, ConstantInt::get(In->getType(), ShAmt),
                              In->getName() + ".lobit");
    }

    // Toggle the low bit for "X == 0".
    if (Cmp->getPredicate() == ICmpInst::ICMP_EQ)
      In = Builder.CreateXor(In, ConstantInt::get(In->getType(), 1));

    if (Zext.getType() == In->getType())
      return replaceInstUsesWith(Zext, In);

    Value *IntCast = Builder.CreateIntCast(In, Zext.getType(), false);
    return replaceInstUsesWith(Zext, IntCast);

if (Cmp->isEquality()) {
  // Test if a bit is clear/set using a shifted-one mask:
  // zext (icmp eq (and X, (1 << ShAmt)), 0) --> and (lshr (not X), ShAmt), 1
  // zext (icmp ne (and X, (1 << ShAmt)), 0) --> and (lshr X, ShAmt), 1
  Value *X, *ShAmt;
  if (Cmp->hasOneUse() && match(Cmp->getOperand(1), m_ZeroInt()) &&
      match(Cmp->getOperand(0),
            m_OneUse(m_c_And(m_Shl(m_One(), m_Value(ShAmt)), m_Value(X))))) {
    auto *And = cast<BinaryOperator>(Cmp->getOperand(0));
    Value *Shift = And->getOperand(X == And->getOperand(0) ? 1 : 0);
    if (Zext.getType() == And->getType() ||
        Cmp->getPredicate() != ICmpInst::ICMP_EQ || Shift->hasOneUse()) {
      if (Cmp->getPredicate() == ICmpInst::ICMP_EQ)
        X = Builder.CreateNot(X);
      Value *Lshr = Builder.CreateLShr(X, ShAmt);
      Value *And1 =
          Builder.CreateAnd(Lshr, ConstantInt::get(X->getType(), 1));
      return replaceInstUsesWith(
          Zext, Builder.CreateZExtOrTrunc(And1, Zext.getType()));

// We need to emit an AND to clear the high bits.
Constant *C = ConstantInt::get(Res->getType(),
                           APInt::getLowBitsSet(DestBitSize, SrcBitsKept));
return BinaryOperator::CreateAnd(Res, C);

Instruction *InstCombinerImpl::transformSExtICmp(ICmpInst *Cmp,
                                                 SExtInst &Sext) {
  Value *Op0 = Cmp->getOperand(0), *Op1 = Cmp->getOperand(1);
  ICmpInst::Predicate Pred = Cmp->getPredicate();

  // Don't bother if Op1 isn't of vector or integer type.
  if (!Op1->getType()->isIntOrIntVectorTy())
    return nullptr;

  if (Pred == ICmpInst::ICMP_SLT && match(Op1, m_ZeroInt())) {
    // sext (x <s 0) --> ashr x, 31 (all ones if negative)
    Value *Sh = ConstantInt::get(Op0->getType(),
                                 Op0->getType()->getScalarSizeInBits() - 1);
    Value *In = Builder.CreateAShr(Op0, Sh, Op0->getName() + ".lobit");
    if (In->getType() != Sext.getType())
      In = Builder.CreateIntCast(In, Sext.getType(), true /*SExt*/);

    return replaceInstUsesWith(Sext, In);

if (!Op1C->isZero() == (Pred == ICmpInst::ICMP_NE)) {
  // sext ((x & 2^n) == 0)   -> (x >> n) - 1
  // sext ((x & 2^n) != 2^n) -> (x >> n) - 1
  unsigned ShiftAmt = KnownZeroMask.countr_zero();
  // Perform a right shift to place the desired bit in the LSB.
  if (ShiftAmt)
    In = Builder.CreateLShr(In,
                            ConstantInt::get(In->getType(), ShiftAmt));

  // At this point "In" is either 1 or 0. Subtract 1 to turn
  // {1, 0} -> {0, -1}.
  In = Builder.CreateAdd(In,
                         ConstantInt::getAllOnesValue(In->getType()),
                         "sext");
} else {
  // sext ((x & 2^n) != 0)   -> (x << bitwidth-n) a>> bitwidth-1
  // sext ((x & 2^n) == 2^n) -> (x << bitwidth-n) a>> bitwidth-1
  unsigned ShiftAmt = KnownZeroMask.countl_zero();
  // Perform a left shift to place the desired bit in the MSB.
  if (ShiftAmt)
    In = Builder.CreateShl(In,
                           ConstantInt::get(In->getType(), ShiftAmt));

  // Distribute the bit over the whole bit width.
  In = Builder.CreateAShr(In, ConstantInt::get(In->getType(),
                          KnownZeroMask.getBitWidth() - 1), "sext");
}

if (Sext.getType() == In->getType())
  return replaceInstUsesWith(Sext, In);
return CastInst::CreateIntegerCast(In, Sext.getType(), true/*SExt*/);

// If we are replacing shifted-in high zero bits with sign bits, convert
// the logic shift to arithmetic shift and eliminate the cast to
// intermediate type:
// sext (trunc (lshr Y, C)) --> sext/trunc (ashr Y, C)
// where C <= truncatedbits && signbits(Y) + C > truncatedbits
Value *Y;
const APInt *C;
if (Src->hasOneUse() &&
    match(X, m_LShr(m_Value(Y), m_APIntAllowPoison(C))) &&
    C->ule(TruncatedBits) &&
    (*C == TruncatedBits ||
     ComputeNumSignBits(Y, &Sext) + C->getZExtValue() > TruncatedBits)) {
  Value *Ashr = Builder.CreateAShr(Y, C->getZExtValue());
  return CastInst::CreateIntegerCast(Ashr, DestTy, /* isSigned */ true);

// We need to emit a shl + ashr to do the sign extend.
Value *ShAmt = ConstantInt::get(DestTy, DestBitSize - SrcBitSize);
return BinaryOperator::CreateAShr(Builder.CreateShl(Res, ShAmt, "sext"),

// Splatting a bit of constant-index across a value:
// sext (ashr (trunc iN X to iM), M-1) to iN --> ashr (shl X, N-M), N-1
// If the dest type is different, use a cast (adjust use check).
if (match(Src, m_OneUse(m_AShr(m_Trunc(m_Value(X)),
                               m_SpecificInt(SrcBitSize - 1))))) {
  Type *XTy = X->getType();
  unsigned XBitSize = XTy->getScalarSizeInBits();
  Constant *ShlAmtC = ConstantInt::get(XTy, XBitSize - SrcBitSize);
  Constant *AshrAmtC = ConstantInt::get(XTy, XBitSize - 1);
  if (XTy == DestTy)
    return BinaryOperator::CreateAShr(Builder.CreateShl(X, ShlAmtC),
                                      AshrAmtC);
  if (cast<BinaryOperator>(Src)->getOperand(0)->hasOneUse()) {
    Value *Ashr = Builder.CreateAShr(Builder.CreateShl(X, ShlAmtC), AshrAmtC);
    return CastInst::CreateIntegerCast(Ashr, DestTy, /* isSigned */ true);

// fpto{u/s}i (fdiv ({u/s}itofp X to F), C_fp) --> {u/s}div X, C
//
// F has precision p (significand bits incl. hidden bit); C_fp is the exact FP
// value of the integer constant C. Given N = integer width, this is safe if:
//   Unsigned: C > 0 and N <= p.
//   Signed:   C != 0 and N - 1 <= p, excluding (X == INT_MIN, C == -1) since
//             sdiv INT_MIN, -1 is UB while the FP path only yields poison.
//             fdiv X, -1 gets transformed to fneg in InstCombine regardless.
//
// The bounds make {u/s}itofp and C_fp exact (every |int| <= 2^p is exact),
// and ensure the rounded quotient never crosses an integer boundary:
//   Rounding lemma: for 0 <= A <= 2^p, 1 <= B <= 2^p, q = floor(A/B),
//     trunc(R_p(A/B)) = q.
//   For r = A - qB > 0, m = q+1, half-gap H(m) <= q/2^p and
//   m - A/B = (B-r)/B >= 1/B > q/2^p >= H(m), so R_p(A/B) < m; q = 0 is
//   similar (H(1) = 2^(-p-1) < 2^-p <= 1/B).
//   Signed case: by symmetry R_p(-z) = -R_p(z), so fptosi yields s*q = sdiv.
bool IsSigned = FI.getOpcode() == Instruction::FPToSI;
Value *X;
const APFloat *APF;
if (IsSigned) {
  if (!match(FI.getOperand(0),
             m_OneUse(m_FDiv(m_SIToFP(m_Value(X)), m_APFloat(APF)))))
    return nullptr;
} else {
  if (!match(FI.getOperand(0),
             m_OneUse(m_FDiv(m_UIToFP(m_Value(X)), m_APFloat(APF)))))
    return nullptr;
}
Type *IntTy = X->getType();
if (FI.getType() != IntTy)
  return nullptr;

unsigned IntWidth = IntTy->getScalarSizeInBits();
unsigned Precision = APFloat::semanticsPrecision(APF->getSemantics());
if (Precision + IsSigned < IntWidth)
  return nullptr;

if (!APF->isInteger())
  return nullptr;

APSInt Divisor(IntWidth, !IsSigned);
bool IsExact = false;
APF->convertToInteger(Divisor, APFloat::rmTowardZero, &IsExact);
if (!IsExact)
  return nullptr;

if (Divisor.isZero())
  return nullptr;

// sdiv INT_MIN, -1 is UB, not poison, so this isn't valid if X == INT_MIN.
// fdiv X, -1 gets transformed to fneg anyways, so we do not handle C == -1.
if (IsSigned && Divisor.isAllOnes())
  return nullptr;

Constant *C = ConstantInt::get(IntTy, Divisor);
return IsSigned ? BinaryOperator::CreateSDiv(X, C)

Instruction *InstCombinerImpl::visitIntToPtr(IntToPtrInst &CI) {
  // If the source integer type is not the intptr_t type for this target, do a
  // trunc or zext to the intptr_t type, then inttoptr of it.  This allows the
  // cast to be exposed to other transforms.
  unsigned AS = CI.getAddressSpace();
  if (CI.getOperand(0)->getType()->getScalarSizeInBits() !=
      DL.getPointerSizeInBits(AS)) {
    Type *Ty = CI.getOperand(0)->getType()->getWithNewType(
        DL.getIntPtrType(CI.getContext(), AS));
    Value *P = Builder.CreateZExtOrTrunc(CI.getOperand(0), Ty);
    return new IntToPtrInst(P, CI.getType());

Instruction *InstCombinerImpl::visitPtrToInt(PtrToIntInst &CI) {
  // If the destination integer type is not the intptr_t type for this target,
  // do a ptrtoint to intptr_t then do a trunc or zext.  This allows the cast
  // to be exposed to other transforms.
  Value *SrcOp = CI.getPointerOperand();
  Type *SrcTy = SrcOp->getType();
  Type *Ty = CI.getType();
  unsigned AS = CI.getPointerAddressSpace();
  unsigned TySize = Ty->getScalarSizeInBits();
  unsigned PtrSize = DL.getPointerSizeInBits(AS);
  if (TySize != PtrSize) {
    Type *IntPtrTy =
        SrcTy->getWithNewType(DL.getIntPtrType(CI.getContext(), AS));
    Value *P = Builder.CreatePtrToInt(SrcOp, IntPtrTy);
    return CastInst::CreateIntegerCast(P, Ty, /*isSigned=*/false);

Instruction *InstCombinerImpl::optimizeBitCastFromPhi(CastInst &CI,
                                                      PHINode *PN) {
  // BitCast used by Store can be handled in InstCombineLoadStoreAlloca.cpp.
  if (hasStoreUsersOnly(CI))
    return nullptr;

  Value *Src = CI.getOperand(0);
  Type *SrcTy = Src->getType();         // Type B
  Type *DestTy = CI.getType();          // Type A

  SmallVector<PHINode *, 4> PhiWorklist;
  SmallSetVector<PHINode *, 4> OldPhiNodes;

  // Find all of the A->B casts and PHI nodes.
  // We need to inspect all related PHI nodes, but PHIs can be cyclic, so
  // OldPhiNodes is used to track all known PHI nodes, before adding a new
  // PHI to PhiWorklist, it is checked against and added to OldPhiNodes first.
  PhiWorklist.push_back(PN);
  OldPhiNodes.insert(PN);
  while (!PhiWorklist.empty()) {
    auto *OldPN = PhiWorklist.pop_back_val();
    for (Value *IncValue : OldPN->incoming_values()) {
      if (isa<Constant>(IncValue))
        continue;

      if (auto *LI = dyn_cast<LoadInst>(IncValue)) {
        // If there is a sequence of one or more load instructions, each loaded
        // value is used as address of later load instruction, bitcast is
        // necessary to change the value type, don't optimize it. For
        // simplicity we give up if the load address comes from another load.
        Value *Addr = LI->getOperand(0);
        if (Addr == &CI || isa<LoadInst>(Addr))
          return nullptr;
        // Don't tranform "load <256 x i32>, <256 x i32>*" to
        // "load x86_amx, x86_amx*", because x86_amx* is invalid.
        // TODO: Remove this check when bitcast between vector and x86_amx
        // is replaced with a specific intrinsic.
        if (DestTy->isX86_AMXTy())
          return nullptr;
        if (LI->hasOneUse() && LI->isSimple())
          continue;
        // If a LoadInst has more than one use, changing the type of loaded
        // value may create another bitcast.
        return nullptr;
      }

      if (auto *PNode = dyn_cast<PHINode>(IncValue)) {
        if (OldPhiNodes.insert(PNode))
          PhiWorklist.push_back(PNode);
        continue;
      }

      auto *BCI = dyn_cast<BitCastInst>(IncValue);
      // We can't handle other instructions.
      if (!BCI)
        return nullptr;

      // Verify it's a A->B cast.
      Type *TyA = BCI->getOperand(0)->getType();
      Type *TyB = BCI->getType();
      if (TyA != DestTy || TyB != SrcTy)
        return nullptr;
    }
  }

  // Check that each user of each old PHI node is something that we can
  // rewrite, so that all of the old PHI nodes can be cleaned up afterwards.
  for (auto *OldPN : OldPhiNodes) {
    for (User *V : OldPN->users()) {
      if (auto *SI = dyn_cast<StoreInst>(V)) {
        if (!SI->isSimple() || SI->getOperand(0) != OldPN)
          return nullptr;
      } else if (auto *BCI = dyn_cast<BitCastInst>(V)) {
        // Verify it's a B->A cast.
        Type *TyB = BCI->getOperand(0)->getType();
        Type *TyA = BCI->getType();
        if (TyA != DestTy || TyB != SrcTy)
          return nullptr;
      } else if (auto *PHI = dyn_cast<PHINode>(V)) {
        // As long as the user is another old PHI node, then even if we don't
        // rewrite it, the PHI web we're considering won't have any users
        // outside itself, so it'll be dead.
        if (!OldPhiNodes.contains(PHI))
          return nullptr;
      } else {
        return nullptr;
      }
    }
  }

  // For each old PHI node, create a corresponding new PHI node with a type A.
  SmallDenseMap<PHINode *, PHINode *> NewPNodes;
  for (auto *OldPN : OldPhiNodes) {
    Builder.SetInsertPoint(OldPN);
    PHINode *NewPN = Builder.CreatePHI(DestTy, OldPN->getNumOperands());
    NewPNodes[OldPN] = NewPN;
  }

  // Fill in the operands of new PHI nodes.
  for (auto *OldPN : OldPhiNodes) {
    PHINode *NewPN = NewPNodes[OldPN];
    for (unsigned j = 0, e = OldPN->getNumOperands(); j != e; ++j) {
      Value *V = OldPN->getOperand(j);
      Value *NewV = nullptr;
      if (auto *C = dyn_cast<Constant>(V)) {
        NewV = ConstantExpr::getBitCast(C, DestTy);
      } else if (auto *LI = dyn_cast<LoadInst>(V)) {
        // Explicitly perform load combine to make sure no opposing transform
        // can remove the bitcast in the meantime and trigger an infinite loop.
        Builder.SetInsertPoint(LI);
        NewV = combineLoadToNewType(*LI, DestTy);
        // Remove the old load and its use in the old phi, which itself becomes
        // dead once the whole transform finishes.
        replaceInstUsesWith(*LI, PoisonValue::get(LI->getType()));
        eraseInstFromFunction(*LI);
      } else if (auto *BCI = dyn_cast<BitCastInst>(V)) {
        NewV = BCI->getOperand(0);
      } else if (auto *PrevPN = dyn_cast<PHINode>(V)) {
        NewV = NewPNodes[PrevPN];
      }
      assert(NewV);
      NewPN->addIncoming(NewV, OldPN->getIncomingBlock(j));
    }
  }

  // Traverse all accumulated PHI nodes and process its users,
  // which are Stores and BitcCasts. Without this processing
  // NewPHI nodes could be replicated and could lead to extra
  // moves generated after DeSSA.
  // If there is a store with type B, change it to type A.


  // Replace users of BitCast B->A with NewPHI. These will help
  // later to get rid off a closure formed by OldPHI nodes.
  Instruction *RetVal = nullptr;
  for (auto *OldPN : OldPhiNodes) {
    PHINode *NewPN = NewPNodes[OldPN];
    for (User *V : make_early_inc_range(OldPN->users())) {
      if (auto *SI = dyn_cast<StoreInst>(V)) {
        assert(SI->isSimple() && SI->getOperand(0) == OldPN);
        Builder.SetInsertPoint(SI);
        auto *NewBC =
          cast<BitCastInst>(Builder.CreateBitCast(NewPN, SrcTy));
        SI->setOperand(0, NewBC);
        Worklist.push(SI);
        assert(hasStoreUsersOnly(*NewBC));
      }
      else if (auto *BCI = dyn_cast<BitCastInst>(V)) {
        Type *TyB = BCI->getOperand(0)->getType();
        Type *TyA = BCI->getType();
        assert(TyA == DestTy && TyB == SrcTy);
        (void) TyA;
        (void) TyB;
        Instruction *I = replaceInstUsesWith(*BCI, NewPN);
        if (BCI == &CI)
          RetVal = I;
      } else if (auto *PHI = dyn_cast<PHINode>(V)) {
        assert(OldPhiNodes.contains(PHI));
        (void) PHI;
      } else {
        llvm_unreachable("all uses should be handled");
      }
    }
  }

  return RetVal;

