  // (X / C1) * C --> X * (C / C1)
  Constant *CDivC1 =
      ConstantFoldBinaryOpOperands(Instruction::FDiv, C, C1, DL);
  if (CDivC1 && CDivC1->isNormalFP())
    return BinaryOperator::CreateFMulFMF(X, CDivC1, FMF);

  // If the constant was a denormal, try reassociating differently.
  // (X / C1) * C --> X / (C1 / C)
  Constant *C1DivC =
      ConstantFoldBinaryOpOperands(Instruction::FDiv, C1, C, DL);
  if (C1DivC && Op0->hasOneUse() && C1DivC->isNormalFP())
    return BinaryOperator::CreateFDivFMF(X, C1DivC, FMF);
}

if (match(Op0, m_OneUse(m_FAdd(m_Value(X), m_Constant(C1))))) {
  // (X + C1) * C --> (X * C) + (C * C1)
  if (Constant *CC1 =
          ConstantFoldBinaryOpOperands(Instruction::FMul, C, C1, DL)) {
    Value *XC = Builder.CreateFMulFMF(X, C, FMF);
    return BinaryOperator::CreateFAddFMF(XC, CC1, FMF);
  }

if (match(Op0, m_OneUse(m_FSub(m_Constant(C1), m_Value(X))))) {
  // (C1 - X) * C --> (C * C1) - (X * C)
  if (Constant *CC1 =
          ConstantFoldBinaryOpOperands(Instruction::FMul, C, C1, DL)) {
    Value *XC = Builder.CreateFMulFMF(X, C, FMF);
    return BinaryOperator::CreateFSubFMF(CC1, XC, FMF);
  }

if (match(Op1, m_OneUse(m_Select(m_Value(Cond), m_One(), m_Value(DivY)))) &&
    IsSafeDivisor(DivY)) {
  Value *NewDiv =
      Builder.CreateExactBinOp(I.getOpcode(), Op0, DivY, I.isExact());
  return SelectInst::Create(Cond, Op0, NewDiv, "", nullptr,
                            cast<SelectInst>(Op1));

if (match(Op1, m_OneUse(m_Select(m_Value(Cond), m_One(), m_Value(DivY)))) &&
    IsSafeDivisor(DivY)) {
  Value *NewDiv =
      Builder.CreateExactBinOp(I.getOpcode(), Op0, DivY, I.isExact());
  return SelectInst::Create(Cond, Op0, NewDiv, "", nullptr,
                            cast<SelectInst>(Op1));

if (match(Op1, m_OneUse(m_Select(m_Value(Cond), m_Value(DivY), m_One()))) &&
    IsSafeDivisor(DivY)) {
  Value *NewDiv =
      Builder.CreateExactBinOp(I.getOpcode(), Op0, DivY, I.isExact());
  return SelectInst::Create(Cond, NewDiv, Op0, "", nullptr,
                            cast<SelectInst>(Op1));

if (match(Op1, m_OneUse(m_Select(m_Value(Cond), m_Value(DivY), m_One()))) &&
    IsSafeDivisor(DivY)) {
  Value *NewDiv =
      Builder.CreateExactBinOp(I.getOpcode(), Op0, DivY, I.isExact());
  return SelectInst::Create(Cond, NewDiv, Op0, "", nullptr,
                            cast<SelectInst>(Op1));

// log2(zext X) -> zext log2(X)
// FIXME: Require one use?
Value *X, *Y;
if (match(Op, m_ZExt(m_Value(X))))
  if (Value *LogX = takeLog2(X, Depth, AssumeNonZero, DoFold))
    return IfFold([&]() { return Builder.CreateZExt(LogX, Op->getType()); });

// log2(trunc x) -> trunc log2(X)
// FIXME: Require one use?
if (match(Op, m_Trunc(m_Value(X)))) {
  auto *TI = cast<TruncInst>(Op);
  if (AssumeNonZero || TI->hasNoUnsignedWrap())
    if (Value *LogX = takeLog2(X, Depth, AssumeNonZero, DoFold))
      return IfFold([&]() {
        return Builder.CreateTrunc(LogX, Op->getType(), "",
                                   /*IsNUW=*/TI->hasNoUnsignedWrap());
      });
}

// log2(Cond ? X : Y) -> Cond ? log2(X) : log2(Y)
// FIXME: Require one use?
if (SelectInst *SI = dyn_cast<SelectInst>(Op))
  if (Value *LogX = takeLog2(SI->getOperand(1), Depth, AssumeNonZero, DoFold))
    if (Value *LogY =
            takeLog2(SI->getOperand(2), Depth, AssumeNonZero, DoFold))
      return IfFold([&]() {
        return Builder.CreateSelect(SI->getOperand(0), LogX, LogY, "", SI);
      });

// Op0 / C where C is large (negative) --> zext (Op0 >= C)
// This also handles non-constant values where the sign bit is known to be
// set.
Type *Ty = I.getType();
if (isKnownNegative(Op1, SQ.getWithInstruction(&I))) {
  Value *Cmp = Builder.CreateICmpUGE(Op0, Op1);
  return CastInst::CreateZExtOrBitCast(Cmp, Ty);
}

// Op0 / (sext i1 X) --> zext (Op0 == -1) (if X is 0, the div is undefined)
if (match(Op1, m_SExt(m_Value(X))) && X->getType()->isIntOrIntVectorTy(1)) {
  Value *Cmp = Builder.CreateICmpEQ(Op0, ConstantInt::getAllOnesValue(Ty));
  return CastInst::CreateZExtOrBitCast(Cmp, Ty);
}

static Instruction *
convertFSqrtDivIntoFMul(CallInst *CI, Instruction *X,
                        const SmallPtrSetImpl<Instruction *> &R1,
                        const SmallPtrSetImpl<Instruction *> &R2,
                        InstCombiner::BuilderTy &B, InstCombinerImpl *IC) {

  B.SetInsertPoint(X);

  // Have an instruction that is representative of all of instructions in R1 and
  // get the most common fpmath metadata and fast-math flags on it.
  Value *SqrtOp = CI->getArgOperand(0);
  auto *FDiv = cast<Instruction>(
      B.CreateFDiv(ConstantFP::get(X->getType(), 1.0), SqrtOp));
  auto *R1FPMathMDNode = (*R1.begin())->getMetadata(LLVMContext::MD_fpmath);
  FastMathFlags R1FMF = (*R1.begin())->getFastMathFlags(); // Common FMF
  for (Instruction *I : R1) {
    R1FPMathMDNode = MDNode::getMostGenericFPMath(
        R1FPMathMDNode, I->getMetadata(LLVMContext::MD_fpmath));
    R1FMF &= I->getFastMathFlags();
    IC->replaceInstUsesWith(*I, FDiv);
    IC->eraseInstFromFunction(*I);
  }
  FDiv->setMetadata(LLVMContext::MD_fpmath, R1FPMathMDNode);
  FDiv->copyFastMathFlags(R1FMF);

  // Have a single sqrt call instruction that is representative of all of
  // instructions in R2 and get the most common fpmath metadata and fast-math
  // flags on it.
  auto *FSqrt = cast<CallInst>(CI->clone());
  FSqrt->insertBefore(CI->getIterator());
  auto *R2FPMathMDNode = (*R2.begin())->getMetadata(LLVMContext::MD_fpmath);
  FastMathFlags R2FMF = (*R2.begin())->getFastMathFlags(); // Common FMF
  for (Instruction *I : R2) {
    R2FPMathMDNode = MDNode::getMostGenericFPMath(
        R2FPMathMDNode, I->getMetadata(LLVMContext::MD_fpmath));
    R2FMF &= I->getFastMathFlags();
    IC->replaceInstUsesWith(*I, FSqrt);
    IC->eraseInstFromFunction(*I);
  }
  FSqrt->setMetadata(LLVMContext::MD_fpmath, R2FPMathMDNode);
  FSqrt->copyFastMathFlags(R2FMF);

  Instruction *FMul;
  // If X = -1/sqrt(a) initially,then FMul = -(FDiv * FSqrt)
  if (match(X, m_FDiv(m_SpecificFP(-1.0), m_Specific(CI)))) {
    Value *Mul = B.CreateFMul(FDiv, FSqrt);
    FMul = cast<Instruction>(B.CreateFNeg(Mul));
  } else
    FMul = cast<Instruction>(B.CreateFMul(FDiv, FSqrt));
  FMul->copyMetadata(*X);
  FMul->copyFastMathFlags(FastMathFlags::intersectRewrite(R1FMF, R2FMF) |
                          FastMathFlags::unionValue(R1FMF, R2FMF));
  return IC->replaceInstUsesWith(*X, FMul);

if (I.hasAllowReassoc() && Op0->hasOneUse() && Op1->hasOneUse()) {
  // sin(X) / cos(X) -> tan(X)
  // cos(X) / sin(X) -> 1/tan(X) (cotangent)
  Value *X;
  bool IsTan = match(Op0, m_Intrinsic<Intrinsic::sin>(m_Value(X))) &&
               match(Op1, m_Intrinsic<Intrinsic::cos>(m_Specific(X)));
  bool IsCot =
      !IsTan && match(Op0, m_Intrinsic<Intrinsic::cos>(m_Value(X))) &&
                match(Op1, m_Intrinsic<Intrinsic::sin>(m_Specific(X)));

  if ((IsTan || IsCot) && hasFloatFn(M, &TLI, I.getType(), LibFunc_tan,
                                     LibFunc_tanf, LibFunc_tanl)) {
    IRBuilder<> B(&I);
    IRBuilder<>::FastMathFlagGuard FMFGuard(B);
    B.setFastMathFlags(I.getFastMathFlags());
    AttributeList Attrs =
        cast<CallBase>(Op0)->getCalledFunction()->getAttributes();
    Value *Res = emitUnaryFloatFnCall(X, &TLI, LibFunc_tan, LibFunc_tanf,
                                      LibFunc_tanl, B, Attrs);
    if (IsCot)
      Res = B.CreateFDiv(ConstantFP::get(I.getType(), 1.0), Res);
    return replaceInstUsesWith(I, Res);
  }
}

// 1 urem X -> zext(X != 1)
if (match(Op0, m_One())) {
  Value *Cmp = Builder.CreateICmpNE(Op1, ConstantInt::get(Ty, 1));
  return CastInst::CreateZExtOrBitCast(Cmp, Ty);
}

case Instruction::And: {
  Constant *ShAmt;
  // sub(0,and(lshr(x,C),1)) --> add(ashr(shl(x,(BW-1)-C),BW-1),0)
  // Only applies when this is a true negation (LHS is zero).  For the
  // general sub(y,and(lshr(x,C),1)) case the rewrite replaces one 2-insn
  // sequence with another without reducing instruction count, and the
  // resulting shl/ashr form prevents later target-specific combines (e.g.
  // on PowerPC the original lshr+and maps to a single rldicl, while the
  // shl+ashr form requires sldi+sradi).
  if (IsTrulyNegation &&
      match(I, m_And(m_OneUse(m_TruncOrSelf(
                         m_LShr(m_Value(X), m_ImmConstant(ShAmt)))),
                     m_One()))) {
    unsigned BW = X->getType()->getScalarSizeInBits();
    Constant *BWMinusOne = ConstantInt::get(X->getType(), BW - 1);
    Value *R = Builder.CreateShl(X, Builder.CreateSub(BWMinusOne, ShAmt));
    R = Builder.CreateAShr(R, BWMinusOne);
    return Builder.CreateTruncOrBitCast(R, I->getType());
  }
  break;

  PHINode *NewPtrPHI = PHINode::Create(
      IntToPtr->getType(), PN.getNumIncomingValues(), PN.getName() + ".ptr");

  InsertNewInstBefore(NewPtrPHI, PN.getIterator());
  SmallDenseMap<Value *, Instruction *> Casts;
  for (auto Incoming : zip(PN.blocks(), AvailablePtrVals)) {
    auto *IncomingBB = std::get<0>(Incoming);
    auto *IncomingVal = std::get<1>(Incoming);

    if (IncomingVal->getType() == IntToPtr->getType()) {
      NewPtrPHI->addIncoming(IncomingVal, IncomingBB);
      continue;
    }

#ifndef NDEBUG
    LoadInst *LoadI = dyn_cast<LoadInst>(IncomingVal);
    assert((isa<PHINode>(IncomingVal) ||
            IncomingVal->getType()->isPointerTy() ||
            (LoadI && LoadI->hasOneUse())) &&
           "Can not replace LoadInst with multiple uses");
#endif
    // Need to insert a BitCast.
    // For an integer Load instruction with a single use, the load + IntToPtr
    // cast will be simplified into a pointer load:
    // %v = load i64, i64* %a.ip, align 8
    // %v.cast = inttoptr i64 %v to float **
    // ==>
    // %v.ptrp = bitcast i64 * %a.ip to float **
    // %v.cast = load float *, float ** %v.ptrp, align 8
    Instruction *&CI = Casts[IncomingVal];
    if (!CI) {
      CI = CastInst::CreateBitOrPointerCast(IncomingVal, IntToPtr->getType(),
                                            IncomingVal->getName() + ".ptr");
      if (auto *IncomingI = dyn_cast<Instruction>(IncomingVal)) {
        BasicBlock::iterator InsertPos(IncomingI);
        InsertPos++;
        BasicBlock *BB = IncomingI->getParent();
        if (isa<PHINode>(IncomingI))
          InsertPos = BB->getFirstInsertionPt();
        assert(InsertPos != BB->end() && "should have checked above");
        InsertNewInstBefore(CI, InsertPos);
      } else {
        auto *InsertBB = &IncomingBB->getParent()->getEntryBlock();
        InsertNewInstBefore(CI, InsertBB->getFirstInsertionPt());
      }
    }
    NewPtrPHI->addIncoming(CI, IncomingBB);
  }

  // Explicitly replace the inttoptr (rather than inserting a ptrtoint) here,
  // to make sure another transform can't undo it in the meantime.
  replaceInstUsesWith(*IntToPtr, NewPtrPHI);
  eraseInstFromFunction(*IntToPtr);
  eraseInstFromFunction(PN);
  return true;

// All incoming values are zexts or constants that are safe to truncate.
// Create a new phi node of the narrow type, phi together all of the new
// operands, and zext the result back to the original type.
PHINode *NewPhi = PHINode::Create(NarrowType, NumIncomingValues,
                                  Phi.getName() + ".shrunk");
for (unsigned I = 0; I != NumIncomingValues; ++I)
  NewPhi->addIncoming(NewIncoming[I], Phi.getIncomingBlock(I));

InsertNewInstBefore(NewPhi, Phi.getIterator());
auto *CI = CastInst::CreateZExtOrBitCast(NewPhi, Phi.getType());

// We use a dropped location here because the new ZExt is necessarily a merge
// of ZExtInsts and at least one constant from incoming branches; the presence
// of the constant means we have no viable DebugLoc from that branch, and
// therefore we must use a dropped location.
CI->setDebugLoc(DebugLoc::getDropped());
return CI;

// Make sure one of the select arms is a power-of-2.
if (!TC.isPowerOf2() && !FC.isPowerOf2())
  return nullptr;

// Determine which shift is needed to transform result of the 'and' into the
// desired result.
const APInt &ValC = !TC.isZero() ? TC : FC;
unsigned ValZeros = ValC.logBase2();
unsigned AndZeros = AndMask.logBase2();
bool ShouldNotVal = !TC.isZero();
bool NeedShift = ValZeros != AndZeros;
bool NeedZExtTrunc =
    SelType->getScalarSizeInBits() != V->getType()->getScalarSizeInBits();

// If we would need to create an 'and' + 'shift' + 'xor' + cast to replace
// a 'select' + 'icmp', then this transformation would result in more
// instructions and potentially interfere with other folding.
if (CreateAnd + ShouldNotVal + NeedShift + NeedZExtTrunc >
    1 + CondVal->hasOneUse())
  return nullptr;

// Insert the 'and' instruction on the input to the truncate.
if (CreateAnd)
  V = Builder.CreateAnd(V, ConstantInt::get(V->getType(), AndMask));

// If types don't match, we can still convert the select by introducing a zext
// or a trunc of the 'and'.
if (ValZeros > AndZeros) {
  V = Builder.CreateZExtOrTrunc(V, SelType);
  V = Builder.CreateShl(V, ValZeros - AndZeros);
} else if (ValZeros < AndZeros) {
  V = Builder.CreateLShr(V, AndZeros - ValZeros);
  V = Builder.CreateZExtOrTrunc(V, SelType);
} else {
  V = Builder.CreateZExtOrTrunc(V, SelType);
}

// Okay, now we know that everything is set up, we just don't know whether we
// have a icmp_ne or icmp_eq and whether the true or false val is the zero.
if (ShouldNotVal)
  V = Builder.CreateXor(V, ValC);

return V;

if (auto *TGEP = dyn_cast<GetElementPtrInst>(TI)) {
  auto *FGEP = cast<GetElementPtrInst>(FI);
  Type *ElementType = TGEP->getSourceElementType();
  return GetElementPtrInst::Create(
      ElementType, Op0, Op1, TGEP->getNoWrapFlags() & FGEP->getNoWrapFlags());

static Instruction *
tryToReuseConstantFromSelectInComparison(SelectInst &Sel, ICmpInst &Cmp,
                                         InstCombinerImpl &IC) {
  CmpPredicate Pred;
  Value *X;
  Constant *C0;
  if (!match(&Cmp, m_OneUse(m_ICmp(
                       Pred, m_Value(X),
                       m_CombineAnd(m_AnyIntegralConstant(), m_Constant(C0))))))
    return nullptr;

  // If comparison predicate is non-relational, we won't be able to do anything.
  if (ICmpInst::isEquality(Pred))
    return nullptr;

  // If comparison predicate is non-canonical, then we certainly won't be able
  // to make it canonical; canonicalizeCmpWithConstant() already tried.
  if (!InstCombiner::isCanonicalPredicate(Pred))
    return nullptr;

  // If the [input] type of comparison and select type are different, lets abort
  // for now. We could try to compare constants with trunc/[zs]ext though.
  if (C0->getType() != Sel.getType())
    return nullptr;

  // ULT with 'add' of a constant is canonical. See foldICmpAddConstant().
  // FIXME: Are there more magic icmp predicate+constant pairs we must avoid?
  //        Or should we just abandon this transform entirely?
  if (Pred == CmpInst::ICMP_ULT && match(X, m_Add(m_Value(), m_Constant())))
    return nullptr;


  Value *SelVal0, *SelVal1; // We do not care which one is from where.
  match(&Sel, m_Select(m_Value(), m_Value(SelVal0), m_Value(SelVal1)));
  // At least one of these values we are selecting between must be a constant
  // else we'll never succeed.
  if (!match(SelVal0, m_AnyIntegralConstant()) &&
      !match(SelVal1, m_AnyIntegralConstant()))
    return nullptr;

  // Does this constant C match any of the `select` values?
  auto MatchesSelectValue = [SelVal0, SelVal1](Constant *C) {
    return C->isElementWiseEqual(SelVal0) || C->isElementWiseEqual(SelVal1);
  };

  // If C0 *already* matches true/false value of select, we are done.
  if (MatchesSelectValue(C0))
    return nullptr;

  // Check the constant we'd have with flipped-strictness predicate.
  auto FlippedStrictness = getFlippedStrictnessPredicateAndConstant(Pred, C0);
  if (!FlippedStrictness)
    return nullptr;

  // If said constant doesn't match either, then there is no hope,
  if (!MatchesSelectValue(FlippedStrictness->second))
    return nullptr;

  // It matched! Lets insert the new comparison just before select.
  InstCombiner::BuilderTy::InsertPointGuard Guard(IC.Builder);
  IC.Builder.SetInsertPoint(&Sel);

  Pred = ICmpInst::getSwappedPredicate(Pred); // Yes, swapped.
  Value *NewCmp = IC.Builder.CreateICmp(Pred, X, FlippedStrictness->second,
                                        Cmp.getName() + ".inv");
  IC.replaceOperand(Sel, 0, NewCmp);
  Sel.swapValues();
  Sel.swapProfMetadata();

  return &Sel;

if (Pred == ICmpInst::ICMP_SGT && match(CmpRHS, m_AllOnes()) &&
    !match(TrueVal, m_Constant()) && !match(FalseVal, m_Constant()) &&
    ICI->hasOneUse()) {
  InstCombiner::BuilderTy::InsertPointGuard Guard(Builder);
  Builder.SetInsertPoint(&SI);
  Value *IsNeg = Builder.CreateIsNeg(CmpLHS, ICI->getName());
  replaceOperand(SI, 0, IsNeg);
  SI.swapValues();
  SI.swapProfMetadata();
  return &SI;

Value *OrV = Builder.CreateSelectWithUnknownProfile(NotC, One, TrueVal,
                                                    DEBUG_TYPE);
return createSelectInstWithUnknownProfile(FalseVal, OrV, Zero);

Value *AndV = Builder.CreateSelectWithUnknownProfile(NotC, FalseVal, Zero,
                                                     DEBUG_TYPE);
return createSelectInstWithUnknownProfile(TrueVal, One, AndV);

if (TrueSI->hasOneUse()) {
  Value *And = nullptr, *OtherVal = nullptr;
  // select(C0, select(C1, a, b), b) -> select(C0&&C1, a, b)
  if (TrueSI->getFalseValue() == FalseVal) {
    And = Builder.CreateLogicalAnd(CondVal, TrueSI->getCondition(), "",
                                   &SI);
    OtherVal = TrueSI->getTrueValue();
  }
  // select(C0, select(C1, b, a), b) -> select(C0&&!C1, a, b)
  else if (TrueSI->getTrueValue() == FalseVal) {
    Value *InvertedCond = Builder.CreateNot(TrueSI->getCondition());
    And = Builder.CreateLogicalAnd(CondVal, InvertedCond, "", &SI);
    OtherVal = TrueSI->getFalseValue();
  }
  if (And && OtherVal) {
    replaceOperand(SI, 0, And);
    replaceOperand(SI, 1, OtherVal);
    setExplicitlyUnknownBranchWeightsIfProfiled(SI, DEBUG_TYPE);
    return &SI;

if (TrueSI->hasOneUse()) {
  Value *And = nullptr, *OtherVal = nullptr;
  // select(C0, select(C1, a, b), b) -> select(C0&&C1, a, b)
  if (TrueSI->getFalseValue() == FalseVal) {
    And = Builder.CreateLogicalAnd(CondVal, TrueSI->getCondition(), "",
                                   &SI);
    OtherVal = TrueSI->getTrueValue();
  }
  // select(C0, select(C1, b, a), b) -> select(C0&&!C1, a, b)
  else if (TrueSI->getTrueValue() == FalseVal) {
    Value *InvertedCond = Builder.CreateNot(TrueSI->getCondition());
    And = Builder.CreateLogicalAnd(CondVal, InvertedCond, "", &SI);
    OtherVal = TrueSI->getFalseValue();
  }
  if (And && OtherVal) {
    replaceOperand(SI, 0, And);
    replaceOperand(SI, 1, OtherVal);
    setExplicitlyUnknownBranchWeightsIfProfiled(SI, DEBUG_TYPE);
    return &SI;

if (FalseSI->hasOneUse()) {
  Value *Or = nullptr, *OtherVal = nullptr;
  // select(C0, a, select(C1, a, b)) -> select(C0||C1, a, b)
  if (FalseSI->getTrueValue() == TrueVal) {
    Or = Builder.CreateLogicalOr(CondVal, FalseSI->getCondition(), "",
                                 &SI);
    OtherVal = FalseSI->getFalseValue();
  }
  // select(C0, a, select(C1, b, a)) -> select(C0||!C1, a, b)
  else if (FalseSI->getFalseValue() == TrueVal) {
    Value *InvertedCond = Builder.CreateNot(FalseSI->getCondition());
    Or = Builder.CreateLogicalOr(CondVal, InvertedCond, "", &SI);
    OtherVal = FalseSI->getTrueValue();
  }
  if (Or && OtherVal) {
    replaceOperand(SI, 0, Or);
    replaceOperand(SI, 2, OtherVal);
    setExplicitlyUnknownBranchWeightsIfProfiled(SI, DEBUG_TYPE);
    return &SI;

if (FalseSI->hasOneUse()) {
  Value *Or = nullptr, *OtherVal = nullptr;
  // select(C0, a, select(C1, a, b)) -> select(C0||C1, a, b)
  if (FalseSI->getTrueValue() == TrueVal) {
    Or = Builder.CreateLogicalOr(CondVal, FalseSI->getCondition(), "",
                                 &SI);
    OtherVal = FalseSI->getFalseValue();
  }
  // select(C0, a, select(C1, b, a)) -> select(C0||!C1, a, b)
  else if (FalseSI->getFalseValue() == TrueVal) {
    Value *InvertedCond = Builder.CreateNot(FalseSI->getCondition());
    Or = Builder.CreateLogicalOr(CondVal, InvertedCond, "", &SI);
    OtherVal = FalseSI->getTrueValue();
  }
  if (Or && OtherVal) {
    replaceOperand(SI, 0, Or);
    replaceOperand(SI, 2, OtherVal);
    setExplicitlyUnknownBranchWeightsIfProfiled(SI, DEBUG_TYPE);
    return &SI;

if (Op1->hasOneUse() && match(Op1, m_SRem(m_Value(A), m_Constant(C))) &&
    match(C, m_Power2())) {
  // FIXME: Should this get moved into SimplifyDemandedBits by saying we don't
  // demand the sign bit (and many others) here??
  Constant *Mask = ConstantExpr::getSub(C, ConstantInt::get(Ty, 1));
  Value *Rem = Builder.CreateAnd(A, Mask, Op1->getName());
  return replaceOperand(I, 1, Rem);

if (ShAmtC >= WidthDiff) {
  // (bswap (zext X)) >> C --> zext (bswap X >> C')
  Value *NewShift = Builder.CreateLShr(NarrowSwap, ShAmtC - WidthDiff);
  return new ZExtInst(NewShift, Ty);
} else {

  // (bswap (zext X)) >> C --> (zext (bswap X)) << C'
  Value *NewZExt = Builder.CreateZExt(NarrowSwap, Ty);
  Constant *ShiftDiff = ConstantInt::get(Ty, WidthDiff - ShAmtC);
  return BinaryOperator::CreateShl(NewZExt, ShiftDiff);
}

// If any of the bits being shifted in are demanded, then we should set
// the sign bit as demanded.
bool ShiftedInBitsDemanded = DemandedMask.countl_zero() < ShiftAmt;
if (ShiftedInBitsDemanded)
  DemandedMaskIn.setSignBit();
if (SimplifyDemandedBits(I, 0, DemandedMaskIn, Known, Q, Depth + 1)) {
  // exact flag may not longer hold.
  I->dropPoisonGeneratingFlags();
  return I;
}

// If the input sign bit is known to be zero, or if none of the shifted in
// bits are demanded, turn this into an unsigned shift right.
if (Known.Zero[BitWidth - 1] || !ShiftedInBitsDemanded) {
  BinaryOperator *LShr = BinaryOperator::CreateLShr(I->getOperand(0),
                                                    I->getOperand(1));
  LShr->setIsExact(cast<BinaryOperator>(I)->isExact());
  LShr->takeName(I);
  return InsertNewInstWith(LShr, I->getIterator());

}
case Intrinsic::ctpop: {
  // Checking if the number of clear bits is odd (parity)? If the type has
  // an even number of bits, that's the same as checking if the number of
  // set bits is odd, so we can eliminate the 'not' op.
  Value *X;
  if (DemandedMask == 1 && VTy->getScalarSizeInBits() % 2 == 0 &&
      match(II->getArgOperand(0), m_Not(m_Value(X)))) {
    Function *Ctpop = Intrinsic::getOrInsertDeclaration(
        II->getModule(), Intrinsic::ctpop, VTy);
    return InsertNewInstWith(CallInst::Create(Ctpop, {X}), I->getIterator());
  }
  break;

// (ptrmask (getelementptr i8, ptr p, imm i), imm mask)
//   -> (ptrmask (getelementptr i8, ptr p, imm (i & mask)), imm mask)
