// If we have a PHI node with a vector type that is only used to feed
// itself and be an operand of extractelement at a constant location,
// try to replace the PHI of the vector type with a PHI of a scalar type.
Instruction *InstCombinerImpl::scalarizePHI(ExtractElementInst &EI,
                                            PHINode *PN) {
  SmallVector<Instruction *, 2> Extracts;
  // The users we want the PHI to have are:
  // 1) The EI ExtractElement (we already know this)
  // 2) Possibly more ExtractElements with the same index.
  // 3) Another operand, which will feed back into the PHI.
  Instruction *PHIUser = nullptr;
  for (auto *U : PN->users()) {
    if (ExtractElementInst *EU = dyn_cast<ExtractElementInst>(U)) {
      if (EI.getIndexOperand() == EU->getIndexOperand())
        Extracts.push_back(EU);
      else
        return nullptr;
    } else if (!PHIUser) {
      PHIUser = cast<Instruction>(U);
    } else {
      return nullptr;
    }
  }

  if (!PHIUser)
    return nullptr;

  // Verify that this PHI user has one use, which is the PHI itself,
  // and that it is a binary operation which is cheap to scalarize.
  // otherwise return nullptr.
  if (!PHIUser->hasOneUse() || !(PHIUser->user_back() == PN) ||
      !(isa<BinaryOperator>(PHIUser)) ||
      !cheapToScalarize(PHIUser, EI.getIndexOperand()))
    return nullptr;

  // Create a scalar PHI node that will replace the vector PHI node
  // just before the current PHI node.
  PHINode *scalarPHI = cast<PHINode>(InsertNewInstWith(
      PHINode::Create(EI.getType(), PN->getNumIncomingValues(), ""), PN->getIterator()));
  // Scalarize each PHI operand. A switch may produce multiple edges from the
  // same predecessor; reuse the scalar instruction for duplicate edges.
  SmallDenseMap<BasicBlock *, Value *, 4> ScalarizedValues;
  for (unsigned i = 0; i < PN->getNumIncomingValues(); i++) {
    Value *PHIInVal = PN->getIncomingValue(i);
    BasicBlock *inBB = PN->getIncomingBlock(i);
    Value *Elt = EI.getIndexOperand();

    // Reuse scalar value for duplicate edges from the same predecessor.
    if (Value *Existing = ScalarizedValues.lookup(inBB)) {
      scalarPHI->addIncoming(Existing, inBB);
      continue;
    }

    Value *ScalarVal;
    // If the operand is the PHI induction variable:
    if (PHIInVal == PHIUser) {
      // Scalarize the binary operation. One operand is the
      // scalar PHI, and the other is extracted from the other
      // vector operand.
      BinaryOperator *B0 = cast<BinaryOperator>(PHIUser);
      unsigned opId = (B0->getOperand(0) == PN) ? 1 : 0;
      Value *Op = InsertNewInstWith(
          ExtractElementInst::Create(B0->getOperand(opId), Elt,
                                     B0->getOperand(opId)->getName() + ".Elt"),
          B0->getIterator());
      // Preserve operand order for binary operation to preserve semantics of
      // non-commutative operations.
      Value *FirstOp = (B0->getOperand(0) == PN) ? scalarPHI : Op;
      Value *SecondOp = (B0->getOperand(0) == PN) ? Op : scalarPHI;
      ScalarVal = InsertNewInstWith(BinaryOperator::CreateWithCopiedFlags(
                                        B0->getOpcode(), FirstOp, SecondOp, B0),
                                    B0->getIterator());
    } else {
      // Scalarize PHI input:
      Instruction *newEI = ExtractElementInst::Create(PHIInVal, Elt, "");
      // Insert the new instruction into the predecessor basic block.
      Instruction *pos = dyn_cast<Instruction>(PHIInVal);
      BasicBlock::iterator InsertPos;
      if (pos && !isa<PHINode>(pos)) {
        InsertPos = ++pos->getIterator();
      } else {
        InsertPos = inBB->getFirstInsertionPt();
      }

      ScalarVal = InsertNewInstWith(newEI, InsertPos);
    }

    ScalarizedValues[inBB] = ScalarVal;
    scalarPHI->addIncoming(ScalarVal, inBB);
  }

  for (auto *E : Extracts) {
    replaceInstUsesWith(*E, scalarPHI);
    // Add old extract to worklist for DCE.
    addToWorklist(E);
  }

  return &EI;
}

/// Fold a variable extract from a vector of pointers that all point into the
/// same object at a constant stride
static Value *
foldExtractOfStridedPointerVector(ExtractElementInst &EI,
                                  InstCombiner::BuilderTy &Builder,
                                  const DataLayout &DL) {
  auto *VecTy = dyn_cast<FixedVectorType>(EI.getVectorOperandType());
  if (!VecTy || !VecTy->getElementType()->isPointerTy())
    return nullptr;

  unsigned NumElts = VecTy->getNumElements();
  if (NumElts < 2)
    return nullptr;

  // Every lane must resolve to the same base pointer plus a constant byte
  // offset. findScalarElement returns poison for a lane the vector never
  // defines; that poison is its own base, so a vector mixing defined and
  // undefined lanes fails the base comparison below.
  unsigned IdxWidth = DL.getIndexTypeSizeInBits(VecTy->getElementType());
  Value *Base = nullptr;
  SmallVector<APInt> Offsets;
  for (unsigned I = 0; I != NumElts; ++I) {
    Value *Elt = findScalarElement(EI.getVectorOperand(), I);
    if (!Elt)
      return nullptr;
    Value *EltBase;
    const APInt *C;
    APInt Offset(IdxWidth, 0);
    // m_Value may bind even when the offset is not constant, so reset it.
    if (match(Elt, m_PtrAdd(m_Value(EltBase), m_APInt(C))))
      Offset = C->sextOrTrunc(IdxWidth);
    else
      EltBase = Elt;
    if (I == 0)
      Base = EltBase;
    else if (Base != EltBase)
      return nullptr;
    Offsets.push_back(Offset);
  }

  // The offsets must form an arithmetic sequence.
  APInt Stride = Offsets[1] - Offsets[0];
  for (unsigned I = 1; I != NumElts; ++I)
    if (Offsets[I] - Offsets[0] != Stride * I)
      return nullptr;

  // Index off the common base, not off element 0: an element may be poison in
  // a lane the extract never selects. The base is an operand of every element
  // and the new GEPs have no flags, so the result is never more poisonous.
  Type *IdxTy = DL.getIndexType(VecTy->getElementType());
  Value *Idx = Builder.CreateZExtOrTrunc(EI.getIndexOperand(), IdxTy);
  Value *Ptr = Builder.CreatePtrAdd(
      Base, Builder.CreateMul(Idx, ConstantInt::get(IdxTy, Stride)));
  return Builder.CreatePtrAdd(Ptr, ConstantInt::get(IdxTy, Offsets[0]));
}

if (match(SrcVec, m_UnOp(UO)) && cheapToScalarize(SrcVec, Index)) {
  // extelt (unop X), Index --> unop (extelt X, Index)
  Value *X = UO->getOperand(0);
  Value *E = Builder.CreateExtractElement(X, Index);
  return UnaryOperator::CreateWithCopiedFlags(UO->getOpcode(), E, UO);
}

// If the binop is not speculatable, we cannot hoist the extractelement if
// it may make the operand poison.
BinaryOperator *BO;
if (match(SrcVec, m_BinOp(BO)) && cheapToScalarize(SrcVec, Index) &&
    (HasKnownValidIndex ||
     isSafeToSpeculativelyExecuteWithVariableReplaced(BO))) {
  // extelt (binop X, Y), Index --> binop (extelt X, Index), (extelt Y, Index)
  Value *X = BO->getOperand(0), *Y = BO->getOperand(1);
  Value *E0 = Builder.CreateExtractElement(X, Index);
  Value *E1 = Builder.CreateExtractElement(Y, Index);
  return BinaryOperator::CreateWithCopiedFlags(BO->getOpcode(), E0, E1, BO);
}

Value *X, *Y;
CmpPredicate Pred;
if (match(SrcVec, m_Cmp(Pred, m_Value(X), m_Value(Y))) &&
    cheapToScalarize(SrcVec, Index)) {
  // extelt (cmp X, Y), Index --> cmp (extelt X, Index), (extelt Y, Index)
  Value *E0 = Builder.CreateExtractElement(X, Index);
  Value *E1 = Builder.CreateExtractElement(Y, Index);
  CmpInst *SrcCmpInst = cast<CmpInst>(SrcVec);
  return CmpInst::CreateWithCopiedFlags(SrcCmpInst->getOpcode(), Pred, E0, E1,
                                        SrcCmpInst);
}

static Value *evaluateInDifferentElementOrder(Value *V, ArrayRef<int> Mask,
                                              IRBuilderBase &Builder) {
  // Mask.size() does not need to be equal to the number of vector elements.

  assert(V->getType()->isVectorTy() && "can't reorder non-vector elements");
  Type *EltTy = V->getType()->getScalarType();

  if (isa<PoisonValue>(V))
    return PoisonValue::get(FixedVectorType::get(EltTy, Mask.size()));

  if (match(V, m_Undef()))
    return UndefValue::get(FixedVectorType::get(EltTy, Mask.size()));

  if (isa<ConstantAggregateZero>(V))
    return ConstantAggregateZero::get(FixedVectorType::get(EltTy, Mask.size()));

  if (Constant *C = dyn_cast<Constant>(V))
    return ConstantExpr::getShuffleVector(C, PoisonValue::get(C->getType()),
                                          Mask);

  Instruction *I = cast<Instruction>(V);
  switch (I->getOpcode()) {
    case Instruction::Add:
    case Instruction::FAdd:
    case Instruction::Sub:
    case Instruction::FSub:
    case Instruction::Mul:
    case Instruction::FMul:
    case Instruction::UDiv:
    case Instruction::SDiv:
    case Instruction::FDiv:
    case Instruction::URem:
    case Instruction::SRem:
    case Instruction::FRem:
    case Instruction::Shl:
    case Instruction::LShr:
    case Instruction::AShr:
    case Instruction::And:
    case Instruction::Or:
    case Instruction::Xor:
    case Instruction::ICmp:
    case Instruction::FCmp:
    case Instruction::Trunc:
    case Instruction::ZExt:
    case Instruction::SExt:
    case Instruction::FPToUI:
    case Instruction::FPToSI:
    case Instruction::UIToFP:
    case Instruction::SIToFP:
    case Instruction::FPTrunc:
    case Instruction::FPExt:
    case Instruction::Select:
    case Instruction::GetElementPtr: {
      SmallVector<Value*, 8> NewOps;
      bool NeedsRebuild =
          (Mask.size() !=
           cast<FixedVectorType>(I->getType())->getNumElements());
      for (int i = 0, e = I->getNumOperands(); i != e; ++i) {
        Value *V;
        // Recursively call evaluateInDifferentElementOrder on vector arguments
        // as well. E.g. GetElementPtr may have scalar operands even if the
        // return value is a vector, so we need to examine the operand type.
        if (I->getOperand(i)->getType()->isVectorTy())
          V = evaluateInDifferentElementOrder(I->getOperand(i), Mask, Builder);
        else
          V = I->getOperand(i);
        NewOps.push_back(V);
        NeedsRebuild |= (V != I->getOperand(i));
      }
      if (NeedsRebuild)
        return buildNew(I, NewOps, Builder);
      return I;
    }
    case Instruction::InsertElement: {
      int Element = cast<ConstantInt>(I->getOperand(2))->getLimitedValue();

      // The insertelement was inserting at Element. Figure out which element
      // that becomes after shuffling. The answer is guaranteed to be unique
      // by CanEvaluateShuffled.
      bool Found = false;
      int Index = 0;
      for (int e = Mask.size(); Index != e; ++Index) {
        if (Mask[Index] == Element) {
          Found = true;
          break;
        }
      }

      // If element is not in Mask, no need to handle the operand 1 (element to
      // be inserted). Just evaluate values in operand 0 according to Mask.
      if (!Found)
        return evaluateInDifferentElementOrder(I->getOperand(0), Mask, Builder);

      Value *V = evaluateInDifferentElementOrder(I->getOperand(0), Mask,
                                                 Builder);
      Builder.SetInsertPoint(I);
      return Builder.CreateInsertElement(V, I->getOperand(1), Index);
    }
  }
  llvm_unreachable("failed to reorder elements of vector instruction!");
}

case Instruction::Sub:
  R = Builder.CreateAdd(CtpopOfNotOp, ConstantExpr::getSub(C, BitWidthC));
  break;

case Instruction::Add:
  R = Builder.CreateSub(ConstantExpr::getAdd(C, BitWidthC), CtpopOfNotOp);
  break;

case Instruction::Add:
  R = Builder.CreateSub(ConstantExpr::getAdd(C, BitWidthC), CtpopOfNotOp);
  break;

case Instruction::ICmp:
  R = Builder.CreateICmp(cast<ICmpInst>(I)->getSwappedPredicate(),
                         CtpopOfNotOp, ConstantExpr::getSub(BitWidthC, C));
  break;
default:
  llvm_unreachable("Unhandled Opcode");
}
assert(R != nullptr);
return replaceInstUsesWith(*I, R);

// If the value used in the zext/sext is the select condition, or the negated
// of the select condition, the binop can be simplified.
if (CondVal == A) {
  Value *NewTrueVal = NewFoldedConst(false, TrueVal);
  return SelectInst::Create(CondVal, NewTrueVal,
                            NewFoldedConst(true, FalseVal), "", nullptr, SI);
}

if (match(A, m_Not(m_Specific(CondVal)))) {
  Value *NewTrueVal = NewFoldedConst(true, TrueVal);
  return SelectInst::Create(CondVal, NewTrueVal,
                            NewFoldedConst(false, FalseVal), "", nullptr, SI);
}

      Clone = InsertNewInstBefore(Clone, OpBB->getTerminator()->getIterator());
      Clones.insert({OpBB, Clone});
      // We may have speculated the instruction.
      Clone->dropUBImplyingAttrsAndMetadata();
    }

    NewPhiValues[OpIndex] = Clone;
  }

  // Okay, we can do the transformation: create the new PHI node.
  PHINode *NewPN = PHINode::Create(I.getType(), PN->getNumIncomingValues());
  InsertNewInstBefore(NewPN, PN->getIterator());
  NewPN->takeName(PN);
  NewPN->setDebugLoc(PN->getDebugLoc());

  for (unsigned i = 0; i != NumPHIValues; ++i)
    NewPN->addIncoming(NewPhiValues[i], PN->getIncomingBlock(i));

  if (IdenticalUsers) {
    // Collect and deduplicate users up-front to avoid iterator invalidation.
    SmallSetVector<Instruction *, 4> ToReplace;
    for (User *U : PN->users()) {
      Instruction *User = cast<Instruction>(U);
      if (User == &I)
        continue;
      ToReplace.insert(User);
    }
    for (Instruction *I : ToReplace) {
      replaceInstUsesWith(*I, NewPN);
      eraseInstFromFunction(*I);
    }
    OneUse = true;
  }

  if (OneUse) {
    replaceAllDbgUsesWith(*PN, *NewPN, *PN, DT);
  }
  return replaceInstUsesWith(I, NewPN);
}

static Instruction *foldGEPOfPhi(GetElementPtrInst &GEP, PHINode *PN,
                                 IRBuilderBase &Builder) {
  auto *Op1 = dyn_cast<GetElementPtrInst>(PN->getOperand(0));
  if (!Op1)
    return nullptr;

  // Don't fold a GEP into itself through a PHI node. This can only happen
  // through the back-edge of a loop. Folding a GEP into itself means that
  // the value of the previous iteration needs to be stored in the meantime,
  // thus requiring an additional register variable to be live, but not
  // actually achieving anything (the GEP still needs to be executed once per
  // loop iteration).
  if (Op1 == &GEP)
    return nullptr;
  GEPNoWrapFlags NW = Op1->getNoWrapFlags();

  int DI = -1;

  for (auto I = PN->op_begin()+1, E = PN->op_end(); I !=E; ++I) {
    auto *Op2 = dyn_cast<GetElementPtrInst>(*I);
    if (!Op2 || Op1->getNumOperands() != Op2->getNumOperands() ||
        Op1->getSourceElementType() != Op2->getSourceElementType())
      return nullptr;

    // As for Op1 above, don't try to fold a GEP into itself.
    if (Op2 == &GEP)
      return nullptr;

    // Keep track of the type as we walk the GEP.
    Type *CurTy = nullptr;

    for (unsigned J = 0, F = Op1->getNumOperands(); J != F; ++J) {
      if (Op1->getOperand(J)->getType() != Op2->getOperand(J)->getType())
        return nullptr;

      if (Op1->getOperand(J) != Op2->getOperand(J)) {
        if (DI == -1) {
          // We have not seen any differences yet in the GEPs feeding the
          // PHI yet, so we record this one if it is allowed to be a
          // variable.

          // The first two arguments can vary for any GEP, the rest have to be
          // static for struct slots
          if (J > 1) {
            assert(CurTy && "No current type?");
            if (CurTy->isStructTy())
              return nullptr;
          }

          DI = J;
        } else {
          // The GEP is different by more than one input. While this could be
          // extended to support GEPs that vary by more than one variable it
          // doesn't make sense since it greatly increases the complexity and
          // would result in an R+R+R addressing mode which no backend
          // directly supports and would need to be broken into several
          // simpler instructions anyway.
          return nullptr;
        }
      }

      // Sink down a layer of the type for the next iteration.
      if (J > 0) {
        if (J == 1) {
          CurTy = Op1->getSourceElementType();
        } else {
          CurTy =
              GetElementPtrInst::getTypeAtIndex(CurTy, Op1->getOperand(J));
        }
      }
    }

    NW &= Op2->getNoWrapFlags();
  }

  // If not all GEPs are identical we'll have to create a new PHI node.
  // Check that the old PHI node has only one use so that it will get
  // removed.
  if (DI != -1 && !PN->hasOneUse())
    return nullptr;

  auto *NewGEP = cast<GetElementPtrInst>(Op1->clone());
  NewGEP->setNoWrapFlags(NW);

  if (DI == -1) {
    // All the GEPs feeding the PHI are identical. Clone one down into our
    // BB so that it can be merged with the current GEP.
  } else {
    // All the GEPs feeding the PHI differ at a single offset. Clone a GEP
    // into the current block so it can be merged, and create a new PHI to
    // set that index.
    PHINode *NewPN;
    {
      IRBuilderBase::InsertPointGuard Guard(Builder);
      Builder.SetInsertPoint(PN);
      NewPN = Builder.CreatePHI(Op1->getOperand(DI)->getType(),
                                PN->getNumOperands());
    }

    for (auto &I : PN->operands())
      NewPN->addIncoming(cast<GEPOperator>(I)->getOperand(DI),
                         PN->getIncomingBlock(I));

    NewGEP->setOperand(DI, NewPN);
  }

  NewGEP->insertBefore(*GEP.getParent(), GEP.getParent()->getFirstInsertionPt());
  return NewGEP;
}

// Index width may not be the same width as pointer width.
// Data layout chooses the right type based on supported integer types.
Type *NewScalarIndexTy =
    DL.getIndexType(GEP.getPointerOperandType()->getScalarType());

gep_type_iterator GTI = gep_type_begin(GEP);
for (User::op_iterator I = GEP.op_begin() + 1, E = GEP.op_end(); I != E;
     ++I, ++GTI) {
  // Skip indices into struct types.
  if (GTI.isStruct())
    continue;

  Type *IndexTy = (*I)->getType();
  Type *NewIndexType =
      IndexTy->isVectorTy()
          ? VectorType::get(NewScalarIndexTy,
                            cast<VectorType>(IndexTy)->getElementCount())
          : NewScalarIndexTy;

  // If the element type has zero size then any index over it is equivalent
  // to an index of zero, so replace it with zero if it is not zero already.
  Type *EltTy = GTI.getIndexedType();
  if (EltTy->isSized() && DL.getTypeAllocSize(EltTy).isZero())
    if (!isa<Constant>(*I) || !match(I->get(), m_Zero())) {
      *I = Constant::getNullValue(NewIndexType);
      MadeChange = true;
    }

  if (IndexTy != NewIndexType) {
    // If we are using a wider index than needed for this platform, shrink
    // it to what we need.  If narrower, sign-extend it to what we need.
    // This explicit cast can make subsequent optimizations more obvious.
    if (IndexTy->getScalarSizeInBits() <
        NewIndexType->getScalarSizeInBits()) {
      if (GEP.hasNoUnsignedWrap() && GEP.hasNoUnsignedSignedWrap())
        *I = Builder.CreateZExt(*I, NewIndexType, "", /*IsNonNeg=*/true);
      else
        *I = Builder.CreateSExt(*I, NewIndexType);
    } else {
      *I = Builder.CreateTrunc(*I, NewIndexType, "", GEP.hasNoUnsignedWrap(),
                               GEP.hasNoUnsignedSignedWrap());
    }
    MadeChange = true;
  }
}
if (MadeChange)
  return &GEP;

// Scalarize vector operands; prefer splat-of-gep.as canonical form.
// Note that this looses information about undef lanes; we run it after
// demanded bits to partially mitigate that loss.
if (GEPType->isVectorTy() && llvm::any_of(GEP.operands(), [](Value *Op) {
      return Op->getType()->isVectorTy() && getSplatValue(Op);
    })) {
  SmallVector<Value *> NewOps;
  for (auto &Op : GEP.operands()) {
    if (Op->getType()->isVectorTy())
      if (Value *Scalar = getSplatValue(Op)) {
        NewOps.push_back(Scalar);
        continue;
      }
    NewOps.push_back(Op);
  }

  Value *Res = Builder.CreateGEP(GEP.getSourceElementType(), NewOps[0],
                                 ArrayRef(NewOps).drop_front(), GEP.getName(),
                                 GEP.getNoWrapFlags());
  if (!Res->getType()->isVectorTy()) {
    ElementCount EC = cast<VectorType>(GEPType)->getElementCount();
    Res = Builder.CreateVectorSplat(EC, Res);
  }
  return replaceInstUsesWith(GEP, Res);
}

if (ExactIns->isExact() && ExactIns->hasOneUse()) {
  // Try to canonicalize non-i8 element type to i8 if the index is an
  // exact instruction. If the index is an exact instruction (div/shr)
  // with a constant RHS, we can fold the non-i8 element scale into the
  // div/shr (similiar to the mul case, just inverted).
  const APInt *C;
  std::optional<APInt> NewC;
  if (has_single_bit(TyAllocSize) &&
      match(ExactIns, m_Shr(m_Value(V), m_APInt(C))) &&
      C->uge(countr_zero(TyAllocSize)))
    NewC = *C - countr_zero(TyAllocSize);
  else if (match(ExactIns, m_UDiv(m_Value(V), m_APInt(C)))) {
    APInt Quot;
    uint64_t Rem;
    APInt::udivrem(*C, TyAllocSize, Quot, Rem);
    if (Rem == 0)
      NewC = Quot;
  } else if (match(ExactIns, m_SDiv(m_Value(V), m_APInt(C)))) {
    APInt Quot;
    int64_t Rem;
    APInt::sdivrem(*C, TyAllocSize, Quot, Rem);
    // For sdiv we need to make sure we arent creating INT_MIN / -1.
    if (!Quot.isAllOnes() && Rem == 0)
      NewC = Quot;
  }

  if (NewC.has_value()) {
    Value *NewOp = Builder.CreateExactBinOp(
        static_cast<Instruction::BinaryOps>(ExactIns->getOpcode()), V,
        ConstantInt::get(V->getType(), *NewC), /*IsExact=*/true);
    return GetElementPtrInst::Create(Builder.getInt8Ty(),
                                     GEP.getPointerOperand(), NewOp,
                                     GEP.getNoWrapFlags());
  }
}

// Canonicalize logical-and-with-invert as logical-or-with-invert.
// This is done by inverting the condition and swapping successors:
// br (X && !Y), T, F --> br !(X && !Y), F, T --> br (!X || Y), F, T
Value *Y;
if (isa<SelectInst>(Cond) &&
    match(Cond,
          m_OneUse(m_LogicalAnd(m_Value(X), m_OneUse(m_Not(m_Value(Y))))))) {
  Value *NotX = Builder.CreateNot(X, "not." + X->getName());
  Value *Or = Builder.CreateLogicalOr(NotX, Y);

  // Set weights for the new OR select instruction too.
  if (auto *OrInst = dyn_cast<Instruction>(Or)) {
    if (auto *CondInst = dyn_cast<Instruction>(Cond)) {
      SmallVector<uint32_t> Weights;
      if (extractBranchWeights(*CondInst, Weights)) {
        assert(Weights.size() == 2 && "Unexpected number of branch weights!");
        std::swap(Weights[0], Weights[1]);
        setBranchWeights(*OrInst, Weights, /*IsExpected=*/false);
      }
    }
  }
  BI.swapSuccessors();
  if (BPI)
    BPI->swapSuccEdgesProbabilities(BI.getParent());
  return replaceOperand(BI, 0, Or);

if (auto InvertFn = MaybeInvertible(Cond); InvertFn && Cond->hasOneUse()) {
  for (auto &Case : SI.cases()) {
    const APInt &New = InvertFn(Case.getCaseValue()->getValue(), *CondOpC);
    Case.setValue(ConstantInt::get(SI.getContext(), New));
  }
  return replaceOperand(SI, 0, Op0);
}

uint64_t ShiftAmt;
if (match(Cond, m_Shl(m_Value(Op0), m_ConstantInt(ShiftAmt))) &&
    ShiftAmt < Op0->getType()->getScalarSizeInBits() &&
    all_of(SI.cases(), [&](const auto &Case) {
      return Case.getCaseValue()->getValue().countr_zero() >= ShiftAmt;
    })) {
  // Change 'switch (X << 2) case 4:' into 'switch (X) case 1:'.
  OverflowingBinaryOperator *Shl = cast<OverflowingBinaryOperator>(Cond);
  if (Shl->hasNoUnsignedWrap() || Shl->hasNoSignedWrap() ||
      Shl->hasOneUse()) {
    Value *NewCond = Op0;
    if (!Shl->hasNoUnsignedWrap() && !Shl->hasNoSignedWrap()) {
      // If the shift may wrap, we need to mask off the shifted bits.
      unsigned BitWidth = Op0->getType()->getScalarSizeInBits();
      NewCond = Builder.CreateAnd(
          Op0, APInt::getLowBitsSet(BitWidth, BitWidth - ShiftAmt));
    }
    for (auto Case : SI.cases()) {
      const APInt &CaseVal = Case.getCaseValue()->getValue();
      APInt ShiftedCase = Shl->hasNoSignedWrap() ? CaseVal.ashr(ShiftAmt)
                                                 : CaseVal.lshr(ShiftAmt);
      Case.setValue(ConstantInt::get(SI.getContext(), ShiftedCase));
    }
    return replaceOperand(SI, 0, NewCond);

KnownBits Known = computeKnownBits(Cond, &SI);
unsigned LeadingKnownZeros = Known.countMinLeadingZeros();
unsigned LeadingKnownOnes = Known.countMinLeadingOnes();

// Compute the number of leading bits we can ignore.
// TODO: A better way to determine this would use ComputeNumSignBits().
for (const auto &C : SI.cases()) {
  LeadingKnownZeros =
      std::min(LeadingKnownZeros, C.getCaseValue()->getValue().countl_zero());
  LeadingKnownOnes =
      std::min(LeadingKnownOnes, C.getCaseValue()->getValue().countl_one());
}

unsigned NewWidth = Known.getBitWidth() - std::max(LeadingKnownZeros, LeadingKnownOnes);

// Shrink the condition operand if the new type is smaller than the old type.
// But do not shrink to a non-standard type, because backend can't generate
// good code for that yet.
// TODO: We can make it aggressive again after fixing PR39569.
if (NewWidth > 0 && NewWidth < Known.getBitWidth() &&
    shouldChangeType(Known.getBitWidth(), NewWidth)) {
  IntegerType *Ty = IntegerType::get(SI.getContext(), NewWidth);
  Builder.SetInsertPoint(&SI);
  Value *NewCond = Builder.CreateTrunc(Cond, Ty, "trunc");

  for (auto Case : SI.cases()) {
    APInt TruncatedCase = Case.getCaseValue()->getValue().trunc(NewWidth);
    Case.setValue(ConstantInt::get(SI.getContext(), TruncatedCase));
  }
  return replaceOperand(SI, 0, NewCond);
}

Value *
InstCombinerImpl::pushFreezeToPreventPoisonFromPropagating(FreezeInst &OrigFI) {
  // Try to push freeze through instructions that propagate but don't produce
  // poison as far as possible.  If an operand of freeze follows three
  // conditions 1) one-use, 2) does not produce poison, and 3) has all but one
  // guaranteed-non-poison operands then push the freeze through to the one
  // operand that is not guaranteed non-poison.  The actual transform is as
  // follows.
  //   Op1 = ...                        ; Op1 can be posion
  //   Op0 = Inst(Op1, NonPoisonOps...) ; Op0 has only one use and only have
  //                                    ; single guaranteed-non-poison operands
  //   ... = Freeze(Op0)
  // =>
  //   Op1 = ...
  //   Op1.fr = Freeze(Op1)
  //   ... = Inst(Op1.fr, NonPoisonOps...)
  auto *OrigOp = OrigFI.getOperand(0);
  auto *OrigOpInst = dyn_cast<Instruction>(OrigOp);

  // While we could change the other users of OrigOp to use freeze(OrigOp), that
  // potentially reduces their optimization potential, so let's only do this iff
  // the OrigOp is only used by the freeze.
  if (!OrigOpInst || !OrigOpInst->hasOneUse() || isa<PHINode>(OrigOp))
    return nullptr;

  // We can't push the freeze through an instruction which can itself create
  // poison.  If the only source of new poison is flags, we can simply
  // strip them (since we know the only use is the freeze and nothing can
  // benefit from them.)
  if (canCreateUndefOrPoison(cast<Operator>(OrigOp),
                             /*ConsiderFlagsAndMetadata*/ false))
    return nullptr;

  // If operand is guaranteed not to be poison, there is no need to add freeze
  // to the operand. So we first find the operand that is not guaranteed to be
  // poison.
  Value *MaybePoisonOperand = nullptr;
  for (Value *V : OrigOpInst->operands()) {
    if (isa<MetadataAsValue>(V) || isGuaranteedNotToBeUndefOrPoison(V) ||
        // Treat identical operands as a single operand.
        (MaybePoisonOperand && MaybePoisonOperand == V))
      continue;
    if (!MaybePoisonOperand)
      MaybePoisonOperand = V;
    else
      return nullptr;
  }

  OrigOpInst->dropPoisonGeneratingAnnotations();

  // If all operands are guaranteed to be non-poison, we can drop freeze.
  if (!MaybePoisonOperand)
    return OrigOp;

  Builder.SetInsertPoint(OrigOpInst);
  Value *FrozenMaybePoisonOperand = Builder.CreateFreeze(
      MaybePoisonOperand, MaybePoisonOperand->getName() + ".fr");

  OrigOpInst->replaceUsesOfWith(MaybePoisonOperand, FrozenMaybePoisonOperand);
  return OrigOp;
}

Instruction *InstCombinerImpl::foldFreezeIntoRecurrence(FreezeInst &FI,
                                                        PHINode *PN) {
  // Detect whether this is a recurrence with a start value and some number of
  // backedge values. We'll check whether we can push the freeze through the
  // backedge values (possibly dropping poison flags along the way) until we
  // reach the phi again. In that case, we can move the freeze to the start
  // value.
  Use *StartU = nullptr;
  SmallVector<Value *> Worklist;
  for (Use &U : PN->incoming_values()) {
    if (DT.dominates(PN->getParent(), PN->getIncomingBlock(U))) {
      // Add backedge value to worklist.
      Worklist.push_back(U.get());
      continue;
    }

    // Don't bother handling multiple start values.
    if (StartU)
      return nullptr;
    StartU = &U;
  }

  if (!StartU || Worklist.empty())
    return nullptr; // Not a recurrence.

  Value *StartV = StartU->get();
  BasicBlock *StartBB = PN->getIncomingBlock(*StartU);
  bool StartNeedsFreeze = !isGuaranteedNotToBeUndefOrPoison(StartV);
  // We can't insert freeze if the start value is the result of the
  // terminator (e.g. an invoke).
  if (StartNeedsFreeze && StartBB->getTerminator() == StartV)
    return nullptr;

  SmallPtrSet<Value *, 32> Visited;
  SmallVector<Instruction *> DropFlags;
  while (!Worklist.empty()) {
    Value *V = Worklist.pop_back_val();
    if (!Visited.insert(V).second)
      continue;

    if (Visited.size() > 32)
      return nullptr; // Limit the total number of values we inspect.

    // Assume that PN is non-poison, because it will be after the transform.
    if (V == PN || isGuaranteedNotToBeUndefOrPoison(V))
      continue;

    Instruction *I = dyn_cast<Instruction>(V);
    if (!I || canCreateUndefOrPoison(cast<Operator>(I),
                                     /*ConsiderFlagsAndMetadata*/ false))
      return nullptr;

    DropFlags.push_back(I);
    append_range(Worklist, I->operands());
  }

  for (Instruction *I : DropFlags)
    I->dropPoisonGeneratingAnnotations();

  if (StartNeedsFreeze) {
    Builder.SetInsertPoint(StartBB->getTerminator());
    Value *FrozenStartV = Builder.CreateFreeze(StartV,
                                               StartV->getName() + ".fr");
    replaceUse(*StartU, FrozenStartV);
  }
  return replaceInstUsesWith(FI, PN);
}
